window.CARDS=window.CARDS||{};CARDS["story-v-y3v2-index"]=[{"i":"sc-nanase-tsubasa-y3v2-p10-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"tsukishiro ayanokouji-kiyotaka ayanokouji-atsuomi nanase-tsubasa","q":"nanase tsubasa year 3  vol  2 prologue   depth read  tsukishiro s offer sits beside the unconscious matsuo eiichirou in his hospital room  overwhelmed with regret   how did it come to this   if i d noticed something was wrong with eiichirou kun  this wouldn t have happened   i have brought you an opportunity to exact your revenge   attending anhs is the only way to get close to your target   my apologies  my name is tsukishiro  i ve been well acquainted with you and matsuo kun sleeping here  since you were children   you must mix lies with the truth  her goal has shifted from revenge   to help ayanokoji so he won t become a  pure evil  who creates more victims like eiichirou  is recruited by him to get close to ayanokoji in exchange for revenge  is tasked with approaching him as an insignificant being  now wants to save him  holds him responsible for cornering eiichirou   the true target of her revenge  tsukishiro s mention of  shirogane san  proves he knew nanase since childhood  eiichirou is in a vegetative state   a  prolonged disturbance of consciousness","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p10-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nanase-tsubasa.html#sc-nanase-tsubasa-y3v2-p10-1\">Year 3, Vol. 2 Prologue — depth read: Tsukishiro&#x27;s offer<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/span><\/h3><p class=\"setup\">Sits beside the unconscious Matsuo Eiichirou in his hospital room, overwhelmed with regret.<\/p><p class=\"with\">with <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ayanokouji-atsuomi.html\">Ayanokōji Atsuomi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> &quot;How did it come to this—&quot;<span class=\"pg\">p.10<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> &quot;If I&#x27;d noticed something was wrong with Eiichirou-kun, this wouldn&#x27;t have happened.&quot;<span class=\"pg\">p.10<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Tsukishiro<\/b> &quot;I have brought you an opportunity to exact your revenge.&quot;<span class=\"pg\">p.10<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Attending ANHS is the only way to get close to your target—&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;My apologies. My name is Tsukishiro. I&#x27;ve been well acquainted with you and Matsuo-kun sleeping here, since you were children.&quot;<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;You must mix lies with the truth.&quot;<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Her goal has shifted from revenge — to help Ayanokōji so he won&#x27;t become a &quot;pure evil&quot; who creates more victims like Eiichirou.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Is recruited by him to get close to Ayanokōji in exchange for revenge.<span class=\"pg\">p.10–12<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is tasked with approaching him as an insignificant being; now wants to save him.<span class=\"pg\">p.11–12<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Atsuomi<\/b> Holds him responsible for cornering Eiichirou — the true target of her revenge.<span class=\"pg\">p.12<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Tsukishiro&#x27;s mention of &quot;Shirogane-san&quot; proves he knew Nanase since childhood.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Eiichirou is in a vegetative state — a &quot;prolonged disturbance of consciousness.&quot;<span class=\"pg\">p.10<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p85-1\">→ After: Year 3, Vol. 2 Ch.3 — depth read: Nanase and the first-year fight<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v2-p13-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"shimazaki-ikkei yoshida-kenta ayanokouji-kiyotaka","q":"ayanokoji kiyotaka year 3  vol  2 ch 1   depth read  study secrets and romance he can t feel meets yoshida and shimazaki in the rainy dorm lobby  joins them to keyaki mall   if this was a problem i could solve  i would ve been more than willing to cooperate   to be honest  i hardly ever use these kinds of study guides anymore   you said you envy me  but i m the one who envies you  yoshida   you can honestly say that you re in love with shiraishi   it s not sarcasm  i still don t understand romantic feelings  realizes he cannot share his real study method  white room training is inapplicable  gives partial truths about internet videos and browsing guides  still does not understand romantic feelings despite dating karuizawa  envious of yoshida s ability to feel them  is pressed for his study secrets  gives partial answers and helps him choose study guides  advises him over shiraishi and the romance rumors  discusses his own inability to feel love","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v2-p13-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v2-p13-1\">Year 3, Vol. 2 Ch.1 — depth read: study secrets and romance he can&#x27;t feel<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Meets Yoshida and Shimazaki in the rainy dorm lobby; joins them to Keyaki Mall.<\/p><p class=\"with\">with <a href=\"../../../people/shimazaki-ikkei.html\">Shimazaki Ikkei<\/a> · <a href=\"../../../people/yoshida-kenta.html\">Yoshida Kenta<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;If this was a problem I could solve, I would&#x27;ve been more than willing to cooperate.&quot;<span class=\"pg\">p.18<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;To be honest, I hardly ever use these kinds of study guides anymore.&quot;<span class=\"pg\">p.19<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;You said you envy me, but I&#x27;m the one who envies you, Yoshida.&quot;<span class=\"pg\">p.40<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;You can honestly say that you&#x27;re in love with Shiraishi.&quot;<span class=\"pg\">p.40<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s not sarcasm. I still don&#x27;t understand romantic feelings.&quot;<span class=\"pg\">p.41<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Realizes he cannot share his real study method (White Room training is inapplicable); gives partial truths about internet videos and browsing guides.<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Still does not understand romantic feelings despite dating Karuizawa; envious of Yoshida&#x27;s ability to feel them.<span class=\"pg\">p.40–41<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shimazaki Ikkei<\/b> Is pressed for his study secrets; gives partial answers and helps him choose study guides.<span class=\"pg\">p.16–33<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yoshida Kenta<\/b> Advises him over Shiraishi and the romance rumors; discusses his own inability to feel love.<span class=\"pg\">p.34–42<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v2-p43-1\">→ After: Year 3, Vol. 2 Ch.2 — depth read: the vague exam and the OAA reveal<\/button><\/div><\/article>"},{"i":"sc-shimazaki-ikkei-y3v2-p13-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka yoshida-kenta shiraishi-asuka shimazaki-ikkei","q":"shimazaki ikkei year 3  vol  2 ch 1   depth read  the studious rival is in the dorm lobby listening to english listening practice on a wireless earbud before class   english listening practice for the entrance exams  personally  english isn t my strong suit  so i want to devote as much time as possible to it now  while i still can   i try to set aside at least five hours a day to study  but that s about it   the right to graduate from class a is ultimately just a trump card   today  i m going to make you confess all of your secrets   after seeing the results of the last special exam  i know you re ranked higher than me  i don t expect to catch up to your level today or tomorrow  but that doesn t mean i m going to give up trying   i think nishikawa has special feelings for shiraishi   but information is information  i ll have you pay me back in kind someday  diligent and competitive   studies  5 hours daily  aware of his weaknesses  and determined to close the gap to ayanokoji  sharp analyst of the shiraishi rumor  presses him for study secrets  decides to trust his advice and owes him a future favor  friends with him  debates study habits and the shiraishi rumors  secretly also likes shiraishi  has watched her since enrollment  theorizes about the  100 man slayer  lie and her preferences","h":"<article class=\"card\" id=\"sc-shimazaki-ikkei-y3v2-p13-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shimazaki-ikkei.html#sc-shimazaki-ikkei-y3v2-p13-1\">Year 3, Vol. 2 Ch.1 — depth read: the studious rival<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/shimazaki-ikkei.html\">Shimazaki Ikkei<\/a><\/span><\/h3><p class=\"setup\">Is in the dorm lobby listening to English listening practice on a wireless earbud before class.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/yoshida-kenta.html\">Yoshida Kenta<\/a> · <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shimazaki Ikkei<\/b> &quot;English listening practice for the entrance exams. Personally, English isn&#x27;t my strong suit, so I want to devote as much time as possible to it now, while I still can.&quot;<span class=\"pg\">p.13<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shimazaki Ikkei<\/b> &quot;I try to set aside at least five hours a day to study, but that&#x27;s about it.&quot;<span class=\"pg\">p.14<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shimazaki Ikkei<\/b> &quot;The right to graduate from Class A is ultimately just a trump card.&quot;<span class=\"pg\">p.14<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Today, I&#x27;m going to make you confess all of your secrets.&quot;<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;After seeing the results of the last special exam, I know you&#x27;re ranked higher than me. I don&#x27;t expect to catch up to your level today or tomorrow. But that doesn&#x27;t mean I&#x27;m going to give up trying.&quot;<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I think Nishikawa has special feelings for Shiraishi.&quot;<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;But information is information. I&#x27;ll have you pay me back in kind someday.&quot;<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Diligent and competitive — studies ~5 hours daily, aware of his weaknesses, and determined to close the gap to Ayanokōji; sharp analyst of the Shiraishi rumor.<span class=\"pg\">p.13–32<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Presses him for study secrets; decides to trust his advice and owes him a future favor.<span class=\"pg\">p.16–33<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yoshida Kenta<\/b> Friends with him; debates study habits and the Shiraishi rumors; secretly also likes Shiraishi.<span class=\"pg\">p.13–32<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Has watched her since enrollment; theorizes about the &quot;100-man slayer&quot; lie and her preferences.<span class=\"pg\">p.30–31<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-yoshida-kenta-y3v2-p13-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka shiraishi-asuka shimazaki-ikkei morishita-ai yoshida-kenta","q":"yoshida kenta year 3  vol  2 ch 1   depth read  the lovesick yoshida greets ayanokoji in the dorm lobby  tags along to keyaki mall   yo  mornin   so that s what this is about  well  people naturally tend to rely on me  after all   studying is important  but i wanna take romance seriously  too   what am i supposed to do if shiraishi likes girls  i m a guy  y know  a guy   i wanna go out with shiraishi   i m getting soaked  openly emotional and lovesick   prioritizes romance over studying  is devastated by the rumor  then resolves to pursue shiraishi  wears his feelings openly  acts as go between with shimazaki  confides his feelings and envies gets envied by ayanokoji  is in love with her  calls her mysterious and kind  vows to pursue her  friends with him  is shaken to learn shimazaki is also a rival for shiraishi  refuses to compare her to shiraishi   calls her an  incomprehensible weirdo","h":"<article class=\"card\" id=\"sc-yoshida-kenta-y3v2-p13-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yoshida-kenta.html#sc-yoshida-kenta-y3v2-p13-1\">Year 3, Vol. 2 Ch.1 — depth read: the lovesick Yoshida<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/yoshida-kenta.html\">Yoshida Kenta<\/a><\/span><\/h3><p class=\"setup\">Greets Ayanokōji in the dorm lobby; tags along to Keyaki Mall.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a> · <a href=\"../../../people/shimazaki-ikkei.html\">Shimazaki Ikkei<\/a> · <a href=\"../../../people/morishita-ai.html\">Morishita Ai<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Yoshida Kenta<\/b> &quot;Yo, mornin&#x27;.&quot;<span class=\"pg\">p.13<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yoshida Kenta<\/b> &quot;So that&#x27;s what this is about. Well, people naturally tend to rely on me, after all.&quot;<span class=\"pg\">p.16<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yoshida Kenta<\/b> &quot;Studying is important, but I wanna take romance seriously, too.&quot;<span class=\"pg\">p.21<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;What am I supposed to do if Shiraishi likes girls...? I&#x27;m a guy, y&#x27;know, a guy!&quot;<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I wanna go out with Shiraishi!&quot;<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;m getting soaked!&quot;<span class=\"pg\">p.39<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Openly emotional and lovesick — prioritizes romance over studying, is devastated by the rumor, then resolves to pursue Shiraishi; wears his feelings openly.<span class=\"pg\">p.21–39<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Acts as go-between with Shimazaki; confides his feelings and envies/gets envied by Ayanokōji.<span class=\"pg\">p.13–42<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Is in love with her; calls her mysterious and kind, vows to pursue her.<span class=\"pg\">p.21–39<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shimazaki Ikkei<\/b> Friends with him; is shaken to learn Shimazaki is also a rival for Shiraishi.<span class=\"pg\">p.13–32<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morishita Ai<\/b> Refuses to compare her to Shiraishi — calls her an &quot;incomprehensible weirdo.&quot;<span class=\"pg\">p.38<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yoshida-kenta-y3v2-p52-1\">→ After: Year 3, Vol. 2 Ch.2 — depth read: Yoshida the loyal supporter<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v2-p43-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"nishikawa-ryouko kitou-hayato yoshida-kenta ayanokouji-kiyotaka","q":"ayanokoji kiyotaka year 3  vol  2 ch 2   depth read  the vague exam and the oaa reveal notes third years busily preparing for entrance exams employment  morishita teases him about fitting in during homeroom   if possible  i d like to hear my classmates  opinions first   my opinion is mostly the same as the ones already brought up  the fact that the school deliberately didn t explain the rules this time means it must be something that can be understood and established without explanation   a lot of different opinions have been thrown around  but one that i feel is a strong possibility is that our  attitude in daily life  will be observed for the next week  starting tomorrow   i don t like to stand out  at first  i wasn t even interested in graduating from class a   a major factor was that hashimoto asked me for help  wanting me to do something about the situation where we could no longer win after sakayanagi left  judges the exam s intent is to see how long students can maintain tension toward a vague  undefined goal  at lunch  fielding her skepticism and her  assassin sent by horikita  theory  is questioned by him about why he hid his ability and why he got serious  he leaves the meal early  yoshida defends him and cheers his high oaa as a comrade  ayanokoji s new oaa  academic a   96  physical a  81  adaptability b  66  social contribution b   77  overall b   80  a year earlier it was all c level  academic c 51  physical c  60  adaptability d  37  social c  60  overall c 51","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v2-p43-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v2-p43-1\">Year 3, Vol. 2 Ch.2 — depth read: the vague exam and the OAA reveal<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Notes third-years busily preparing for entrance exams/employment; Morishita teases him about fitting in during homeroom.<\/p><p class=\"with\">with <a href=\"../../../people/nishikawa-ryouko.html\">Nishikawa Ryōko<\/a> · <a href=\"../../../people/kitou-hayato.html\">Kitō Hayato<\/a> · <a href=\"../../../people/yoshida-kenta.html\">Yoshida Kenta<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;If possible, I&#x27;d like to hear my classmates&#x27; opinions first.&quot;<span class=\"pg\">p.45<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;My opinion is mostly the same as the ones already brought up. The fact that the school deliberately didn&#x27;t explain the rules this time means it must be something that can be understood and established without explanation.&quot;<span class=\"pg\">p.49<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;A lot of different opinions have been thrown around, but one that I feel is a strong possibility is that our &#x27;attitude in daily life&#x27; will be observed for the next week, starting tomorrow.&quot;<span class=\"pg\">p.50<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I don&#x27;t like to stand out. At first, I wasn&#x27;t even interested in graduating from Class A.&quot;<span class=\"pg\">p.59<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;A major factor was that Hashimoto asked me for help, wanting me to do something about the situation where we could no longer win after Sakayanagi left.&quot;<span class=\"pg\">p.60<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Judges the exam&#x27;s intent is to see how long students can maintain tension toward a vague, undefined goal.<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nishikawa Ryōko<\/b> At lunch, fielding her skepticism and her &quot;assassin sent by Horikita&quot; theory.<span class=\"pg\">p.55–62<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kitō Hayato<\/b> Is questioned by him about why he hid his ability and why he got serious; he leaves the meal early.<span class=\"pg\">p.58–64<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yoshida Kenta<\/b> Yoshida defends him and cheers his high OAA as a comrade.<span class=\"pg\">p.57–62<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji&#x27;s new OAA: Academic A+ (96), Physical A (81), Adaptability B (66), Social Contribution B+ (77), Overall B+ (80); a year earlier it was all C-level (Academic C 51, Physical C+ 60, Adaptability D+ 37, Social C+ 60, Overall C 51).<span class=\"pg\">p.56<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v2-p13-1\">← Before: Year 3, Vol. 2 Ch.1 — depth read: study secrets and romance he can&#x27;t feel<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v2-p126-1\">→ After: Year 3, Vol. 2 Ch.4 — depth read: 90% certain it&#x27;s conduct<\/button><\/div><\/article>"},{"i":"sc-nishikawa-ryouko-y3v2-p52-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka yoshida-kenta shiraishi-asuka nishikawa-ryouko","q":"nishikawa ryoko year 3  vol  2 ch 2   depth read  nishikawa s skepticism joins the lunch group at shiraishi s invitation  keeps up a running critique of ayanokoji and yoshida   looks like you ve become quite hated  ayanokouji kun   i m more jealous than happy  though   i think blind faith is a dangerous way of thinking   i m still holding on to my theory that you re an assassin sent by horikita san  you know   i can t do it right away  but i guess i do hope i can learn to trust ayanokouji kun as soon as possible   it s hard to tell what kitou kun s thinking  and his face is scary  openly skeptical  negative and teasing   refuses to blindly root for ayanokoji  suspects horikita sent him  but is willing to move toward trust  skeptical of him and his oaa  floats the  assassin  theory before softening  teases him mercilessly as ayanokoji s follower and a second hashimoto  needles him about shiraishi  is her friend  calls her  asuka","h":"<article class=\"card\" id=\"sc-nishikawa-ryouko-y3v2-p52-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nishikawa-ryouko.html#sc-nishikawa-ryouko-y3v2-p52-1\">Year 3, Vol. 2 Ch.2 — depth read: Nishikawa&#x27;s skepticism<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/nishikawa-ryouko.html\">Nishikawa Ryōko<\/a><\/span><\/h3><p class=\"setup\">Joins the lunch group at Shiraishi&#x27;s invitation; keeps up a running critique of Ayanokōji and Yoshida.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/yoshida-kenta.html\">Yoshida Kenta<\/a> · <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nishikawa Ryōko<\/b> &quot;Looks like you&#x27;ve become quite hated, Ayanokouji-kun.&quot;<span class=\"pg\">p.55<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nishikawa Ryōko<\/b> &quot;I&#x27;m more jealous than happy, though~.&quot;<span class=\"pg\">p.57<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nishikawa Ryōko<\/b> &quot;I think blind faith is a dangerous way of thinking.&quot;<span class=\"pg\">p.57<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;m still holding on to my theory that you&#x27;re an assassin sent by Horikita-san, you know.&quot;<span class=\"pg\">p.62<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I can&#x27;t do it right away, but I guess I do hope I can learn to trust Ayanokouji-kun as soon as possible.&quot;<span class=\"pg\">p.62<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s hard to tell what Kitou-kun&#x27;s thinking. And his face is scary.&quot;<span class=\"pg\">p.64<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Openly skeptical, negative and teasing — refuses to blindly root for Ayanokōji, suspects Horikita sent him, but is willing to move toward trust.<span class=\"pg\">p.55–62<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Skeptical of him and his OAA; floats the &quot;assassin&quot; theory before softening.<span class=\"pg\">p.55–62<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yoshida Kenta<\/b> Teases him mercilessly as Ayanokōji&#x27;s follower and a second Hashimoto; needles him about Shiraishi.<span class=\"pg\">p.57–62<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Is her friend; calls her &quot;Asuka.&quot;<span class=\"pg\">p.52–63<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-shiraishi-asuka-y3v2-p52-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka nishikawa-ryouko kitou-hayato shiraishi-asuka","q":"shiraishi asuka year 3  vol  2 ch 2   depth read  shiraishi digs deeper invites ayanokoji to lunch  arranges the group and proposes everyone share private life details   if you d like  would you care to have lunch with me in the cafeteria today   fufufu  doesn t that sound interesting  i m all for it    on including kitou  if you demonstrated your current potential from the very beginning  ayanokouji kun  horikita san s class a would have surely earned more class points by now   you can t truly know someone without seeing their private life  cheerful and sociable  orchestrates the group and steers the conversation toward knowing one another  invites him to lunch  supports him and questions why he hid his ability  friends with her  calls her by first name  approves of including him in the meal","h":"<article class=\"card\" id=\"sc-shiraishi-asuka-y3v2-p52-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiraishi-asuka.html#sc-shiraishi-asuka-y3v2-p52-1\">Year 3, Vol. 2 Ch.2 — depth read: Shiraishi digs deeper<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/span><\/h3><p class=\"setup\">Invites Ayanokōji to lunch; arranges the group and proposes everyone share private-life details.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/nishikawa-ryouko.html\">Nishikawa Ryōko<\/a> · <a href=\"../../../people/kitou-hayato.html\">Kitō Hayato<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;If you&#x27;d like, would you care to have lunch with me in the cafeteria today?&quot;<span class=\"pg\">p.52<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;Fufufu. Doesn&#x27;t that sound interesting? I&#x27;m all for it.&quot; — on including Kitou<span class=\"pg\">p.53<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;If you demonstrated your current potential from the very beginning, Ayanokouji-kun, Horikita-san&#x27;s Class A would have surely earned more Class Points by now.&quot;<span class=\"pg\">p.59<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;You can&#x27;t truly know someone without seeing their private life.&quot;<span class=\"pg\">p.63<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Cheerful and sociable; orchestrates the group and steers the conversation toward knowing one another.<span class=\"pg\">p.52–63<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Invites him to lunch, supports him and questions why he hid his ability.<span class=\"pg\">p.52–63<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nishikawa Ryōko<\/b> Friends with her; calls her by first name.<span class=\"pg\">p.52–63<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kitō Hayato<\/b> Approves of including him in the meal.<span class=\"pg\">p.53<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v2-p127-1\">→ After: Year 3, Vol. 2 Ch.4 — depth read: Shiraishi&#x27;s deliberate mystery<\/button><\/div><\/article>"},{"i":"sc-yoshida-kenta-y3v2-p52-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka nishikawa-ryouko shiraishi-asuka yoshida-kenta","q":"yoshida kenta year 3  vol  2 ch 2   depth read  yoshida the loyal supporter  hey  let s grab a bite to eat  ayanokouji   the special exam s about to start  so maybe they don t want to carelessly give away any information   you re the acting leader of class c now  dude  you really were an amazing guy all along   we re still in the process of feeling each other out   ayanokouji earned that right by getting us through the first special exam  didn t he  cheerfully roots for ayanokoji as a  comrade  and defends him against nishikawa  transparently tries to sit with shiraishi  defends him and starts from a place of trust  argues with her over ayanokoji  she teases him about liking shiraishi  eager to join her for lunch  avoids sitting directly across from her out of shyness","h":"<article class=\"card\" id=\"sc-yoshida-kenta-y3v2-p52-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yoshida-kenta.html#sc-yoshida-kenta-y3v2-p52-1\">Year 3, Vol. 2 Ch.2 — depth read: Yoshida the loyal supporter<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/yoshida-kenta.html\">Yoshida Kenta<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/nishikawa-ryouko.html\">Nishikawa Ryōko<\/a> · <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Yoshida Kenta<\/b> &quot;Hey, let&#x27;s grab a bite to eat, Ayanokouji!&quot;<span class=\"pg\">p.52<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yoshida Kenta<\/b> &quot;The special exam&#x27;s about to start, so maybe they don&#x27;t want to carelessly give away any information?&quot;<span class=\"pg\">p.55<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yoshida Kenta<\/b> &quot;You&#x27;re the acting leader of Class C now. Dude, you really were an amazing guy all along.&quot;<span class=\"pg\">p.57<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;We&#x27;re still in the process of feeling each other out.&quot;<span class=\"pg\">p.62<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Ayanokouji earned that right by getting us through the first special exam, didn&#x27;t he?&quot;<span class=\"pg\">p.62<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Cheerfully roots for Ayanokōji as a &quot;comrade&quot; and defends him against Nishikawa; transparently tries to sit with Shiraishi.<span class=\"pg\">p.55–62<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Defends him and starts from a place of trust.<span class=\"pg\">p.52–62<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nishikawa Ryōko<\/b> Argues with her over Ayanokōji; she teases him about liking Shiraishi.<span class=\"pg\">p.57–62<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Eager to join her for lunch; avoids sitting directly across from her out of shyness.<span class=\"pg\">p.52–63<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yoshida-kenta-y3v2-p13-1\">← Before: Year 3, Vol. 2 Ch.1 — depth read: the lovesick Yoshida<\/button><\/div><\/article>"},{"i":"sc-kitou-hayato-y3v2-p54-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka kitou-hayato","q":"kito hayato year 3  vol  2 ch 2   depth read  kitou s silent scrutiny joins the lunch group at ayanokoji s request  sits silently eating curry rice   i have no interest in other people s oaa ratings   i am interested in the reason why you hid this much ability for two years  and also  why you ve started to get serious now  silent  blunt and observant   uninterested in others  grades but fixated on why ayanokoji hid his ability and why he changed  barely participates and leaves early  presses him on hiding his ability and getting serious  he eats without joining the discussion about getting to know one another and departs abruptly","h":"<article class=\"card\" id=\"sc-kitou-hayato-y3v2-p54-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kitou-hayato.html#sc-kitou-hayato-y3v2-p54-1\">Year 3, Vol. 2 Ch.2 — depth read: Kitou&#x27;s silent scrutiny<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/kitou-hayato.html\">Kitō Hayato<\/a><\/span><\/h3><p class=\"setup\">Joins the lunch group at Ayanokōji&#x27;s request; sits silently eating curry rice.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kitō Hayato<\/b> &quot;I have no interest in other people&#x27;s OAA ratings.&quot;<span class=\"pg\">p.58<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kitō Hayato<\/b> &quot;I am interested in the reason why you hid this much ability for two years. And also… why you&#x27;ve started to get serious now.&quot;<span class=\"pg\">p.58<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Silent, blunt and observant — uninterested in others&#x27; grades but fixated on why Ayanokōji hid his ability and why he changed; barely participates and leaves early.<span class=\"pg\">p.54–64<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Presses him on hiding his ability and getting serious.<span class=\"pg\">p.58<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> He eats without joining the discussion about getting to know one another and departs abruptly.<span class=\"pg\">p.64<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-horikita-suzune-y3v2-p67-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"kouenji-rokusuke nanase-tsubasa karuizawa-kei kushida-kikyou sudou-ken horikita-suzune","q":"horikita suzune year 3  vol  2 ch 3   depth read  horikita s leadership tested calls for calm in class a after chabashira s cold announcement and proposes brainstorming the exam rules   the special exam doesn t start until tomorrow  so just panicking here is a waste of time  first  we should calm down  brainstorm ideas  and discuss things   it s necessary for the class to unite once again  i don t want you to disrupt that harmony   it s true that ayanokouji kun left our class  but we didn t win through his power alone   i m nothing special  i was told i was exceptional quite often back in middle school  but  ayanokouji kun  my brother  nagumo senpai  no  sakayanagi san and ichinose san are the same   hmph  you know  hearing that repeatedly is starting to get on my nerves   if you exhibit no problematic behavior whatsoever  just like the other classmates  i will pay you 200 000 private points   yes    agreeing with koenji that discipline is likely the basis deduces the exam is likely a repeat of the first year conduct test  secures koenji s week of perfect discipline for 500 000 points  and swears sudo to secrecy  stands up to koenji despite his killing intent and blunt criticism of her leadership  rattled but refuses to back down  chases him down twice  strikes a secret deal for his discipline  investigates the first year fight with her in the student council room  consults her at the supermarket about the exam and ayanokoji ichinose  talks with her after ibuki leaves  draws the key insight about chabashira s hint  shares her theory with him  borrows him for the koenji visit  and thanks him","h":"<article class=\"card\" id=\"sc-horikita-suzune-y3v2-p67-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y3v2-p67-1\">Year 3, Vol. 2 Ch.3 — depth read: Horikita&#x27;s leadership tested<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">Calls for calm in Class A after Chabashira&#x27;s cold announcement and proposes brainstorming the exam rules.<\/p><p class=\"with\">with <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a> · <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a> · <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;The special exam doesn&#x27;t start until tomorrow, so just panicking here is a waste of time. First, we should calm down, brainstorm ideas, and discuss things.&quot;<span class=\"pg\">p.67<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;It&#x27;s necessary for the class to unite once again. I don&#x27;t want you to disrupt that harmony.&quot;<span class=\"pg\">p.71<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;It&#x27;s true that Ayanokouji-kun left our class. But we didn&#x27;t win through his power alone.&quot;<span class=\"pg\">p.72<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;m nothing special. I was told I was exceptional quite often back in middle school, but… Ayanokouji-kun, my brother, Nagumo-senpai… no, Sakayanagi-san and Ichinose-san are the same.&quot;<span class=\"pg\">p.87<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Hmph… You know, hearing that repeatedly is starting to get on my nerves.&quot;<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If you exhibit no problematic behavior whatsoever, just like the other classmates, I will pay you 200,000 Private Points.&quot;<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Yes.&quot; — agreeing with Kōenji that discipline is likely the basis<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Deduces the exam is likely a repeat of the first-year conduct test, secures Kōenji&#x27;s week of perfect discipline for 500,000 points, and swears Sudō to secrecy.<span class=\"pg\">p.114–123<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Stands up to Kōenji despite his killing intent and blunt criticism of her leadership; rattled but refuses to back down.<span class=\"pg\">p.71–73<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Chases him down twice; strikes a secret deal for his discipline.<span class=\"pg\">p.69–74, 120–123<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> Investigates the first-year fight with her in the student council room.<span class=\"pg\">p.85–88<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Consults her at the supermarket about the exam and Ayanokōji/Ichinose.<span class=\"pg\">p.89–93<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Talks with her after Ibuki leaves; draws the key insight about Chabashira&#x27;s hint.<span class=\"pg\">p.111–113<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Shares her theory with him, borrows him for the Kōenji visit, and thanks him.<span class=\"pg\">p.115–125<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y3v2-p231-1\">→ After: Year 3, Vol. 2 Epilogue — depth read: investigating Ayanokōji&#x27;s past<\/button><\/div><\/article>"},{"i":"sc-kouenji-rokusuke-y3v2-p69-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"horikita-suzune ayanokouji-kiyotaka sudou-ken kouenji-rokusuke","q":"koenji rokusuke year 3  vol  2 ch 3   depth read  koenji rejects and then sells his discipline walks out of class a s discussion  horikita chases him into the hallway   well  well  horikita girl  is there something i can do for you   i don t mind listening a bit  as long as we re walking   wouldn t that simply be pointless  my time is quite priceless  you see   if the class falls apart simply because i ve left  that just goes to show the limits of your own abilities  horikita girl   being in class a is proof of unity  the only reason the class was lucky enough to win was because ayanokouji boy was making his moves   are you planning to make an enemy of me too  horikita girl   for one week  starting tomorrow i shall sell you my discipline  for the exceptional price of 500 000 private points  arrogant  blunt and self assured  sees through horikita s carrot and threat tactics and warns her with rare killing intent  recognizes independently that the exam is about discipline  70  and doubles her offer to 500 000 points  rebuffs her in the hallway  then accepts a secret 500 000 point deal for one week of good behavior  credits his moves  not class unity  for class a s wins  calls him  red hair kun  claims he is the first man in his room","h":"<article class=\"card\" id=\"sc-kouenji-rokusuke-y3v2-p69-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kouenji-rokusuke.html#sc-kouenji-rokusuke-y3v2-p69-1\">Year 3, Vol. 2 Ch.3 — depth read: Kōenji rejects and then sells his discipline<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/span><\/h3><p class=\"setup\">Walks out of Class A&#x27;s discussion; Horikita chases him into the hallway.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> &quot;Well, well, Horikita Girl. Is there something I can do for you?&quot;<span class=\"pg\">p.70<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> &quot;I don&#x27;t mind listening a bit, as long as we&#x27;re walking.&quot;<span class=\"pg\">p.70<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kōenji Rokusuke<\/b> &quot;Wouldn&#x27;t that simply be pointless? My time is quite priceless, you see.&quot;<span class=\"pg\">p.71<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;If the class falls apart simply because I&#x27;ve left, that just goes to show the limits of your own abilities, Horikita Girl.&quot;<span class=\"pg\">p.71<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Being in Class A is proof of unity? The only reason the class was lucky enough to win was because Ayanokouji-boy was making his moves.&quot;<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Are you planning to make an enemy of me too, Horikita-girl?&quot;<span class=\"pg\">p.74<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;For one week, starting tomorrow—I shall sell you my discipline. For the exceptional price of 500,000 Private Points.&quot;<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Arrogant, blunt and self-assured; sees through Horikita&#x27;s carrot-and-threat tactics and warns her with rare killing intent.<span class=\"pg\">p.70–74<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Recognizes independently that the exam is about discipline (~70%) and doubles her offer to 500,000 points.<span class=\"pg\">p.121–122<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Rebuffs her in the hallway, then accepts a secret 500,000-point deal for one week of good behavior.<span class=\"pg\">p.69–123<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Credits his moves, not class unity, for Class A&#x27;s wins.<span class=\"pg\">p.72<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Calls him &quot;red-hair-kun&quot;; claims he is the first man in his room.<span class=\"pg\">p.121<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p85-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"horikita-suzune nanase-tsubasa","q":"nanase tsubasa year 3  vol  2 ch 3   depth read  nanase and the first year fight works with horikita in the student council room on the case of first years kusanagi and maki   you mean their pride was wounded because they lost a two on one fight  it s not out of the question  but would they really be that tight lipped about it   of course  student council president  but being the president is a lot of work  isn t it  you re amazing  horikita senpai   no mediocre  even so  i think that s fine  a mediocre horikita senpai isn t bad at all   w wha  i i m so sorry  i think student council president horikita is very admirable  helpful but awkward   blurted out the honest view that being mediocre is fine and panicked  trying to smooth it over  assists her in the investigation and is asked to help uncover the truth  the two first years kusanagi minato and maki yuuma got into a fight  neither would report it  hinting a third party  possibly a girl  was involved","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p85-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nanase-tsubasa.html#sc-nanase-tsubasa-y3v2-p85-1\">Year 3, Vol. 2 Ch.3 — depth read: Nanase and the first-year fight<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/span><\/h3><p class=\"setup\">Works with Horikita in the student council room on the case of first-years Kusanagi and Maki.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> &quot;You mean their pride was wounded because they lost a two-on-one fight? It&#x27;s not out of the question, but would they really be that tight-lipped about it?&quot;<span class=\"pg\">p.87<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> &quot;Of course, Student Council President. But being the president is a lot of work, isn&#x27;t it? You&#x27;re amazing, Horikita-senpai.&quot;<span class=\"pg\">p.87<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> &quot;No—mediocre. Even so, I think that&#x27;s fine. A mediocre Horikita-senpai isn&#x27;t bad at all.&quot;<span class=\"pg\">p.88<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;W-Wha—!? I-I&#x27;m so sorry! I think Student Council President Horikita is very admirable!&quot;<span class=\"pg\">p.88<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Helpful but awkward — blurted out the honest view that being mediocre is fine and panicked, trying to smooth it over.<span class=\"pg\">p.87–88<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Assists her in the investigation and is asked to help uncover the truth.<span class=\"pg\">p.85–88<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The two first-years Kusanagi Minato and Maki Yuuma got into a fight; neither would report it, hinting a third party (possibly a girl) was involved.<span class=\"pg\">p.86<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p10-1\">← Before: Year 3, Vol. 2 Prologue — depth read: Tsukishiro&#x27;s offer<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p226-1\">→ After: Year 3, Vol. 2 Ch.7 — depth read: Nanase works the White Room angle<\/button><\/div><\/article>"},{"i":"sc-karuizawa-kei-y3v2-p89-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"horikita-suzune ayanokouji-kiyotaka ichinose-honami karuizawa-kei","q":"karuizawa kei year 3  vol  2 ch 3   depth read  karuizawa s read on ayanokoji meets horikita at the keyaki mall supermarket to discuss the exam   nah  not at all  i was planning to go to the supermarket myself  so don t worry about it   you re really merciless  horikita san  but  y know  i like that about you   ayanokouji kun is lending ichinose san a hand  so that s what you re thinking  is it   if his goal in transferring to class c was to raise it to class a by himself  that s a bit half assed  you know  he should ve just gone to the bottom ranked class d   if it were ayanokouji kun  he would ve gone to class d  even if it meant getting ichinose san expelled  more perceptive than horikita credited  reads ayanokoji as capable of unimaginable things and not needing ichinose s help to reach class a  consulted by her  they grow closer as horikita values her opinion  analyzes his alliance with ichinose and his transfer motives  believes ayanokoji is helping her","h":"<article class=\"card\" id=\"sc-karuizawa-kei-y3v2-p89-1\"><h3><span class=\"ttl\"><a href=\"../../../people/karuizawa-kei.html#sc-karuizawa-kei-y3v2-p89-1\">Year 3, Vol. 2 Ch.3 — depth read: Karuizawa&#x27;s read on Ayanokōji<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/span><\/h3><p class=\"setup\">Meets Horikita at the Keyaki Mall supermarket to discuss the exam.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> &quot;Nah, not at all. I was planning to go to the supermarket myself, so don&#x27;t worry about it.&quot;<span class=\"pg\">p.89<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> &quot;You&#x27;re really merciless, Horikita-san. But, y&#x27;know, I like that about you.&quot;<span class=\"pg\">p.90<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> &quot;Ayanokouji-kun is lending Ichinose-san a hand… So that&#x27;s what you&#x27;re thinking, is it?&quot;<span class=\"pg\">p.91<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;If his goal in transferring to Class C was to raise it to Class A by himself, that&#x27;s a bit half-assed, you know? He should&#x27;ve just gone to the bottom-ranked Class D.&quot;<span class=\"pg\">p.92<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If it were Ayanokouji-kun… he would&#x27;ve gone to Class D, even if it meant getting Ichinose-san expelled.&quot;<span class=\"pg\">p.92<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> More perceptive than Horikita credited; reads Ayanokōji as capable of unimaginable things and not needing Ichinose&#x27;s help to reach Class A.<span class=\"pg\">p.90–93<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Consulted by her; they grow closer as Horikita values her opinion.<span class=\"pg\">p.89–93<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Analyzes his alliance with Ichinose and his transfer motives.<span class=\"pg\">p.91–93<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Believes Ayanokōji is helping her.<span class=\"pg\">p.91<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-karuizawa-kei-y3v2-p231-1\">→ After: Year 3, Vol. 2 Epilogue — depth read: Karuizawa helps investigate<\/button><\/div><\/article>"},{"i":"sc-ibuki-mio-y3v2-p94-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"horikita-suzune ibuki-mio","q":"ibuki mio year 3  vol  2 ch 3   depth read  ibuki s meal and the kick warning comes to horikita s room after 6 30 pm for a meal  after the flying kick she gave her earlier   for a loser  your color s looking a little better  horikita   if it happens again  i ll be sure to kick you then  too  so be grateful  blunt and sarcastic  takes horikita s thanks as praise and laughs off the warning about kicking her in the back  eats at her room  warned not to kick people in the back again  horikita notes ibuki ate every grain of rice  but left a mess   a clue toward the  daily conduct  theory","h":"<article class=\"card\" id=\"sc-ibuki-mio-y3v2-p94-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ibuki-mio.html#sc-ibuki-mio-y3v2-p94-1\">Year 3, Vol. 2 Ch.3 — depth read: Ibuki&#x27;s meal and the kick warning<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/span><\/h3><p class=\"setup\">Comes to Horikita&#x27;s room after 6:30 PM for a meal (after the flying kick she gave her earlier).<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> &quot;For a loser, your color&#x27;s looking a little better, Horikita.&quot;<span class=\"pg\">p.94<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ibuki Mio<\/b> &quot;If it happens again, I&#x27;ll be sure to kick you then, too, so be grateful.&quot;<span class=\"pg\">p.94<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Blunt and sarcastic; takes Horikita&#x27;s thanks as praise and laughs off the warning about kicking her in the back.<span class=\"pg\">p.94–95<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Eats at her room; warned not to kick people in the back again.<span class=\"pg\">p.94–95<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Horikita notes Ibuki ate every grain of rice, but left a mess — a clue toward the &quot;daily conduct&quot; theory.<span class=\"pg\">p.95<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-kushida-kikyou-y3v2-p111-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"horikita-suzune ibuki-mio ayanokouji-kiyotaka kushida-kikyou","q":"kushida kikyo year 3  vol  2 ch 3   depth read  kushida s backhanded support stays behind after ibuki leaves horikita s room  thanks her for the meal and offers help with the exam   thank you for the meal today  i appreciate it   you re not so bad  i suppose  unlike a certain someone  you can actually say thank you   but class c has ayanokouji kun   either way  it doesn t look like you can do it by yourself  horikita san   i just love the cute me who pretends to be kind   i expect your strength isn t just for show  proud and two faced   offers genuine cooperation while openly admitting she loves her own pretend kind persona  still bitter about being in a lower class  thanks her and offers to think about the exam  then leaves with a parting challenge  stayed later partly to avoid discussing exam strategies in front of her  names him as the reason class c is dangerous","h":"<article class=\"card\" id=\"sc-kushida-kikyou-y3v2-p111-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kushida-kikyou.html#sc-kushida-kikyou-y3v2-p111-1\">Year 3, Vol. 2 Ch.3 — depth read: Kushida&#x27;s backhanded support<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a><\/span><\/h3><p class=\"setup\">Stays behind after Ibuki leaves Horikita&#x27;s room; thanks her for the meal and offers help with the exam.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kushida Kikyō<\/b> &quot;Thank you for the meal today. I appreciate it.&quot;<span class=\"pg\">p.111<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kushida Kikyō<\/b> &quot;You&#x27;re not so bad, I suppose. Unlike a certain someone, you can actually say thank you.&quot;<span class=\"pg\">p.111<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kushida Kikyō<\/b> &quot;But Class C has Ayanokouji-kun.&quot;<span class=\"pg\">p.112<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Either way, it doesn&#x27;t look like you can do it by yourself, Horikita-san.&quot;<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I just love the cute me who pretends to be kind.&quot;<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I expect your strength isn&#x27;t just for show.&quot;<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Proud and two-faced — offers genuine cooperation while openly admitting she loves her own pretend-kind persona; still bitter about being in a lower class.<span class=\"pg\">p.111–113<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Thanks her and offers to think about the exam, then leaves with a parting challenge.<span class=\"pg\">p.111–113<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ibuki Mio<\/b> Stayed later partly to avoid discussing exam strategies in front of her.<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Names him as the reason Class C is dangerous.<span class=\"pg\">p.112<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-sudou-ken-y3v2-p115-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"horikita-suzune onodera-kayano kouenji-rokusuke sudou-ken","q":"sudo ken year 3  vol  2 ch 3   depth read  sudo  the reliable ally is in his room studying with onodera when horikita visits late at night   s s s suzune  wh what are you doing here   well  y see  about this special exam  they said we don t gotta study yet  but it d be bad if there was a written test  right   oh  right  they were checkin  stuff like tardiness  absences  and our attitude in class  that s how our class points went to zero  wasn t it   then we gotta make damn sure no one finds out about this   ayanokouji s probably figured it out   but still  isn t five hundred thousand just for doing nothing way too steep   w well  if you re asking me to keep my mouth shut  then i won t tell anyone  flustered and bashful around horikita but dependable   already studying  agrees to keep the plan secret  and helps with koenji without hesitation  is trusted with her exam theory and the koenji deal  silently supportive  which warms her  is studying with her when horikita arrives  accompanies horikita to his room and beats on his door","h":"<article class=\"card\" id=\"sc-sudou-ken-y3v2-p115-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y3v2-p115-1\">Year 3, Vol. 2 Ch.3 — depth read: Sudō, the reliable ally<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><p class=\"setup\">Is in his room studying with Onodera when Horikita visits late at night.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/onodera-kayano.html\">Onodera Kayano<\/a> · <a href=\"../../../people/kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> &quot;S-S-S-Suzune!? Wh-what are you doing here?&quot;<span class=\"pg\">p.115<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> &quot;Well, y&#x27;see, about this special exam. They said we don&#x27;t gotta study yet, but it&#x27;d be bad if there was a written test, right?&quot;<span class=\"pg\">p.115<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> &quot;Oh, right. They were checkin&#x27; stuff like tardiness, absences, and our attitude in class. That&#x27;s how our Class Points went to zero, wasn&#x27;t it?&quot;<span class=\"pg\">p.117<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Then we gotta make damn sure no one finds out about this.&quot;<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Ayanokouji&#x27;s probably figured it out.&quot;<span class=\"pg\">p.118<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;But still, isn&#x27;t five hundred thousand just for doing nothing way too steep?&quot;<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;W-well… If you&#x27;re asking me to keep my mouth shut, then I won&#x27;t tell anyone.&quot;<span class=\"pg\">p.124<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Flustered and bashful around Horikita but dependable — already studying, agrees to keep the plan secret, and helps with Kōenji without hesitation.<span class=\"pg\">p.115–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Is trusted with her exam theory and the Kōenji deal; silently supportive, which warms her.<span class=\"pg\">p.115–125<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Onodera Kayano<\/b> Is studying with her when Horikita arrives.<span class=\"pg\">p.115<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Accompanies Horikita to his room and beats on his door.<span class=\"pg\">p.119–123<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v2-p126-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"shiina-hiyori shiraishi-asuka hashimoto-masayoshi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka year 3  vol  2 ch 4   depth read  90  certain it s conduct tries to leave early for school but is blocked from the elevator by cold eyed class a girls  ends up walking with hiyori   to be precise  it may be more accurate to say that it s not that i don t care about winning or losing  but rather that i can t   over 90  at least  that s my assessment   you can avoid obvious demerits  but you can t earn merits  the only thing we can do is wait for the other classes to make a mistake   if it was only mashima sensei s comment  the probability wouldn t even have reached 50   by the way  how i procured information from the two classes is a trade secret   who can say  it might be twenty million  it might be thirty million  deduces conduct is the exam by comparing the parting words of all four classes  homeroom teachers  deliberately stays cold under ike s accusations so class a will unite against him as a common enemy  painting class c as peaceful  walks with her briefly but struggles to find words  plans to visit the library to apologize properly  walks back with him  is puzzled by her reintroducing herself and her deliberate mystery  discusses the exam and intel with him at the cafe  notes that a high stakes exam with expulsion may come next  morishita cites  15 expulsions the previous year","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v2-p126-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v2-p126-1\">Year 3, Vol. 2 Ch.4 — depth read: 90% certain it&#x27;s conduct<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Tries to leave early for school but is blocked from the elevator by cold-eyed Class A girls; ends up walking with Hiyori.<\/p><p class=\"with\">with <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a> · <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;To be precise, it may be more accurate to say that it&#x27;s not that I don&#x27;t care about winning or losing, but rather that I can&#x27;t.&quot;<span class=\"pg\">p.136<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Over 90%. At least, that&#x27;s my assessment.&quot;<span class=\"pg\">p.137<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;You can avoid obvious demerits, but you can&#x27;t earn merits. The only thing we can do is wait for the other classes to make a mistake.&quot;<span class=\"pg\">p.137<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;If it was only Mashima-sensei&#x27;s comment, the probability wouldn&#x27;t even have reached 50%.&quot;<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;By the way, how I procured information from the two classes is a trade secret.&quot;<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Who can say. It might be twenty million, it might be thirty million.&quot;<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Deduces conduct is the exam by comparing the parting words of all four classes&#x27; homeroom teachers.<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Deliberately stays cold under Ike&#x27;s accusations so Class A will unite against him as a common enemy, painting Class C as peaceful.<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> Walks with her briefly but struggles to find words; plans to visit the library to apologize properly.<span class=\"pg\">p.126–127<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Walks back with him; is puzzled by her reintroducing herself and her deliberate mystery.<span class=\"pg\">p.146–151<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Discusses the exam and intel with him at the café.<span class=\"pg\">p.131–145<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Notes that a high-stakes exam with expulsion may come next; Morishita cites ~15 expulsions the previous year.<span class=\"pg\">p.139<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v2-p43-1\">← Before: Year 3, Vol. 2 Ch.2 — depth read: the vague exam and the OAA reveal<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v2-p152-1\">→ After: Year 3, Vol. 2 Ch.5 — depth read: Yamamura, Hasebe and his own avoidance<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v2-p127-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka shiina-hiyori ike-kanji hashimoto-masayoshi","q":"hashimoto masayoshi year 3  vol  2 ch 4   depth read  hashimoto s intel and ike s anger intercepts ayanokoji and hiyori in the morning  later joins the cafe discussion   yo  good mornin  and mornin  to you too  shiina   ayanokouji kiyotaka  you certainly don t discriminate  do you  are you trying to make a move on shiina hiyori  too   i spent all day yesterday looking into the other classes   you must have a skilled scout  or maybe you ve got a spy planted in there   why re you so bent out of shape about it  it s not like ayanokouji transferred from c to a  eager  gossipy and self serving   investigates other classes  defends ayanokoji for his own benefit  and tries to defuse ike s anger  confirms his group chat instructions and probes his sources  unintentionally drives her away by intercepting them  tries to calm him in the cafe","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v2-p127-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v2-p127-1\">Year 3, Vol. 2 Ch.4 — depth read: Hashimoto&#x27;s intel and Ike&#x27;s anger<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"setup\">Intercepts Ayanokōji and Hiyori in the morning; later joins the café discussion.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a> · <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;&#x27;Yo, good mornin&#x27;. And mornin&#x27; to you too, Shiina.&quot;<span class=\"pg\">p.128<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Ayanokouji Kiyotaka, you certainly don&#x27;t discriminate, do you? Are you trying to make a move on Shiina Hiyori, too?&quot;<span class=\"pg\">p.128<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;I spent all day yesterday looking into the other classes.&quot;<span class=\"pg\">p.132<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;You must have a skilled scout, or maybe you&#x27;ve got a spy planted in there.&quot;<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Why&#x27;re you so bent out of shape about it? It&#x27;s not like Ayanokouji transferred from C to A.&quot;<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Eager, gossipy and self-serving — investigates other classes, defends Ayanokōji for his own benefit, and tries to defuse Ike&#x27;s anger.<span class=\"pg\">p.127–145<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Confirms his group-chat instructions and probes his sources.<span class=\"pg\">p.127–145<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> Unintentionally drives her away by intercepting them.<span class=\"pg\">p.127<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Tries to calm him in the café.<span class=\"pg\">p.141–143<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v2-p164-1\">→ After: Year 3, Vol. 2 Ch.5 — depth read: Hashimoto&#x27;s declaration of loyalty<\/button><\/div><\/article>"},{"i":"sc-shiraishi-asuka-y3v2-p127-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka sakayanagi-arisu morishita-ai shiraishi-asuka","q":"shiraishi asuka year 3  vol  2 ch 4   depth read  shiraishi s deliberate mystery is in the elevator with ayanokoji and walks with him briefly in the morning  interrupts again after school to walk back to school with him   well  i hold our former leader  sakayanagi san  in high regard   may i ask a small question  you ve concluded that the exam is based on our everyday conduct  ayanokouji kun  but what would you say the probability of that is   it seems you based your judgment on mashima sensei s comment to  try to act in a way that befits a student  ayanokouji kun  but i feel that alone is insufficient grounds for such a conclusion   i thought you were a more reserved person  i must say  that was a bold question   there were actually quite a few who  like me  wanted to hold onto hope and believe in you   ahh  that just won t do   i m shiraishi asuka   and you who are you  playful and opaque   reintroduces herself as a test  never answers his question about her  deepening rather than resolving the mystery  walk together  she probes his deduction and then resets their introduction  defends her former leader s legacy against hashimoto  notes his full name speech reminds her of morishita","h":"<article class=\"card\" id=\"sc-shiraishi-asuka-y3v2-p127-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiraishi-asuka.html#sc-shiraishi-asuka-y3v2-p127-1\">Year 3, Vol. 2 Ch.4 — depth read: Shiraishi&#x27;s deliberate mystery<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/span><\/h3><p class=\"setup\">Is in the elevator with Ayanokōji and walks with him briefly in the morning; interrupts again after school to walk back to school with him.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/morishita-ai.html\">Morishita Ai<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;Well, I hold our former leader, Sakayanagi-san, in high regard.&quot;<span class=\"pg\">p.129<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;May I ask a small question? You&#x27;ve concluded that the exam is based on our everyday conduct, Ayanokouji-kun, but what would you say the probability of that is?&quot;<span class=\"pg\">p.137<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;It seems you based your judgment on Mashima-sensei&#x27;s comment to &#x27;try to act in a way that befits a student,&#x27; Ayanokouji-kun, but I feel that alone is insufficient grounds for such a conclusion.&quot;<span class=\"pg\">p.138<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I thought you were a more reserved person. I must say, that was a bold question.&quot;<span class=\"pg\">p.147<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;There were actually quite a few who, like me, wanted to hold onto hope and believe in you.&quot;<span class=\"pg\">p.148<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Ahh... that just won&#x27;t do.&quot;<span class=\"pg\">p.148<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;m Shiraishi Asuka.&quot;<span class=\"pg\">p.148<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;And you—who are you?&quot;<span class=\"pg\">p.148<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Playful and opaque — reintroduces herself as a test, never answers his question about her, deepening rather than resolving the mystery.<span class=\"pg\">p.146–151<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Walk together; she probes his deduction and then resets their introduction.<span class=\"pg\">p.127, 146–151<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Defends her former leader&#x27;s legacy against Hashimoto.<span class=\"pg\">p.129<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morishita Ai<\/b> Notes his full-name speech reminds her of Morishita.<span class=\"pg\">p.148<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v2-p52-1\">← Before: Year 3, Vol. 2 Ch.2 — depth read: Shiraishi digs deeper<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v2-p226-1\">→ After: Year 3, Vol. 2 Ch.7 — depth read: Shiraishi reveals herself as an observer<\/button><\/div><\/article>"},{"i":"sc-ike-kanji-y3v2-p141-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka yamauchi-haruki ike-kanji","q":"ike kanji year 3  vol  2 ch 4   depth read  ike s accusations arrives at the cafe with hondou  forced to sit near ayanokoji s group due to the crowd   crap  ayanokouji again   don t act so familiar  you traitor   yeah  we re class a  but ayanokouji hid how smart he was   i m hearing all sorts of nasty rumors  y know  that you intentionally set up both sakura and maezono to get expelled from the very beginning   i ll never let a guy like you get me expelled  you hear me  bitter and hot headed   blames ayanokoji for every expulsion  works himself into a rage  which ayanokoji deliberately lets happen  vents his anger and hatred at him  brings up the expelled yamauchi as a supposed victim","h":"<article class=\"card\" id=\"sc-ike-kanji-y3v2-p141-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ike-kanji.html#sc-ike-kanji-y3v2-p141-1\">Year 3, Vol. 2 Ch.4 — depth read: Ike&#x27;s accusations<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a><\/span><\/h3><p class=\"setup\">Arrives at the café with Hondou, forced to sit near Ayanokōji&#x27;s group due to the crowd.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ike Kanji<\/b> &quot;Crap... Ayanokouji again...?!&quot;<span class=\"pg\">p.141<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ike Kanji<\/b> &quot;Don&#x27;t act so familiar, you traitor.&quot;<span class=\"pg\">p.141<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ike Kanji<\/b> &quot;Yeah, we&#x27;re Class A, but Ayanokouji hid how smart he was.&quot;<span class=\"pg\">p.142<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;m hearing all sorts of nasty rumors, y&#x27;know. That you intentionally set up both Sakura and Maezono to get expelled from the very beginning.&quot;<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;ll never let a guy like you get me expelled, you hear me!&quot;<span class=\"pg\">p.142<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Bitter and hot-headed — blames Ayanokōji for every expulsion, works himself into a rage (which Ayanokōji deliberately lets happen).<span class=\"pg\">p.141–143<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> vents his anger and hatred at him.<span class=\"pg\">p.141–143<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Brings up the expelled Yamauchi as a supposed victim.<span class=\"pg\">p.142<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v2-p152-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"yamamura-miki hasebe-haruka shiina-hiyori hashimoto-masayoshi ayanokouji-kiyotaka","q":"ayanokoji kiyotaka year 3  vol  2 ch 5   depth read  yamamura  hasebe and his own avoidance is pulled out of his thoughts by morishita tugging his hair  saying yamamura wants to see him   is that so   i want you to find out about shiraishi asuka   i m currently struggling to raise my understanding of the class   then you ll have to be prepared for people to keep secrets from you or avoid you to some extent   it s completely unrelated  so you can rest easy    to hasebe about her fear she caused his transfer  that s not true  i d like to hear it  admits he has been avoiding the library because he doesn t want to see the sadness on hiyori s face after rejecting her invitation  tasks yamamura with investigating her own classmate shiraishi to understand her  meets her  gives her the task of investigating shiraishi  hears her out about the expelled sakura s tv appearances  reflects on avoiding her out of guilt  notes his full commitment to class c","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v2-p152-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v2-p152-1\">Year 3, Vol. 2 Ch.5 — depth read: Yamamura, Hasebe and his own avoidance<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Is pulled out of his thoughts by Morishita tugging his hair, saying Yamamura wants to see him.<\/p><p class=\"with\">with <a href=\"../../../people/yamamura-miki.html\">Yamamura Miki<\/a> · <a href=\"../../../people/hasebe-haruka.html\">Hasebe Haruka<\/a> · <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Is that so?&quot;<span class=\"pg\">p.154<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;I want you to find out about Shiraishi Asuka.&quot;<span class=\"pg\">p.162<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;I&#x27;m currently struggling to raise my understanding of the class.&quot;<span class=\"pg\">p.162<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Then you&#x27;ll have to be prepared for people to keep secrets from you or avoid you to some extent.&quot;<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s completely unrelated, so you can rest easy.&quot; — to Hasebe about her fear she caused his transfer<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;That&#x27;s not true. I&#x27;d like to hear it.&quot;<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Admits he has been avoiding the library because he doesn&#x27;t want to see the sadness on Hiyori&#x27;s face after rejecting her invitation.<span class=\"pg\">p.168–169<\/span><\/li><li><span class=\"mlabel\">Tactic<\/span> Tasks Yamamura with investigating her own classmate Shiraishi to understand her.<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamamura Miki<\/b> Meets her; gives her the task of investigating Shiraishi.<span class=\"pg\">p.152–163<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> Hears her out about the expelled Sakura&#x27;s TV appearances.<span class=\"pg\">p.170–174<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> Reflects on avoiding her out of guilt.<span class=\"pg\">p.168–169<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Notes his full commitment to Class C.<span class=\"pg\">p.164–167<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v2-p126-1\">← Before: Year 3, Vol. 2 Ch.4 — depth read: 90% certain it&#x27;s conduct<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v2-p186-1\">→ After: Year 3, Vol. 2 Ch.6 — depth read: Hoshinomiya&#x27;s test and Hiyori<\/button><\/div><\/article>"},{"i":"sc-morishita-ai-y3v2-p152-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka yamamura-miki hashimoto-masayoshi morishita-ai","q":"morishita ai year 3  vol  2 ch 5   depth read  morishita s comic manipulation tugs ayanokoji s hair from behind and announces yamamura wants to see him  leads him on a deliberately pointless detour   ayanokouji kiyotaka  i must ask you to lend me your face   it appears yamamura miki wishes to see you now   you mustn t be so easily swayed and deceived by the words of others   hmph  that s the ear gun  all those who re caught unaware are startled  you see   how about it  yamamura miki  don t you feel a little less tense now   trust isn t built in a day  eccentric  theatrical and manipulative   plays the straight man comedy routine  tricks ayanokoji into touching a  warm  floor and blows in yamamura s ear  yet her odd methods ease yamamura s tension  leads him to yamamura and claims he owes her  uses the  ear gun  to help her relax  sharply rejects him  trust isn t built in a day","h":"<article class=\"card\" id=\"sc-morishita-ai-y3v2-p152-1\"><h3><span class=\"ttl\"><a href=\"../../../people/morishita-ai.html#sc-morishita-ai-y3v2-p152-1\">Year 3, Vol. 2 Ch.5 — depth read: Morishita&#x27;s comic manipulation<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/morishita-ai.html\">Morishita Ai<\/a><\/span><\/h3><p class=\"setup\">Tugs Ayanokōji&#x27;s hair from behind and announces Yamamura wants to see him; leads him on a deliberately pointless detour.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/yamamura-miki.html\">Yamamura Miki<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;Ayanokouji Kiyotaka. I must ask you to lend me your face.&quot;<span class=\"pg\">p.152<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;It appears Yamamura Miki wishes to see you now.&quot;<span class=\"pg\">p.152<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;You mustn&#x27;t be so easily swayed and deceived by the words of others.&quot;<span class=\"pg\">p.155<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Hmph. That&#x27;s the Ear Gun. All those who&#x27;re caught unaware are startled, you see.&quot;<span class=\"pg\">p.159<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;How about it, Yamamura Miki? Don&#x27;t you feel a little less tense now?&quot;<span class=\"pg\">p.159<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Trust isn&#x27;t built in a day.&quot;<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Eccentric, theatrical and manipulative — plays the straight-man comedy routine, tricks Ayanokōji into touching a &quot;warm&quot; floor and blows in Yamamura&#x27;s ear, yet her odd methods ease Yamamura&#x27;s tension.<span class=\"pg\">p.152–165<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Leads him to Yamamura and claims he owes her.<span class=\"pg\">p.152–163<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamamura Miki<\/b> Uses the &quot;Ear Gun&quot; to help her relax.<span class=\"pg\">p.158–161<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Sharply rejects him (&quot;Trust isn&#x27;t built in a day&quot;).<span class=\"pg\">p.164–165<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-morishita-ai-y3v2-p182-1\">→ After: Year 3, Vol. 2 Ch.6 — depth read: Morishita&#x27;s rubber-band gun<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y3v2-p157-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka morishita-ai shiraishi-asuka yamamura-miki","q":"yamamura miki year 3  vol  2 ch 5   depth read  yamamura s courage to change appears silently outside the south entrance after leading them on a change of meeting place   s sorry   y  yes  since you transferred classes  ayanokouji kun  we still  haven t said a single word to each other  so   i want to change  i want to have more self confidence  to be able to smile in front of others   please let me  help with getting to class a  too   i want to do more  much more  because i believe  there s something  that only i can do   yes  if you re okay with it  ayanokouji kun  i think i can  try to investigate shiraishi san in my own way  extremely shy and passive  but mustering real courage to voice her desire to change  ayanokoji sees it as evolution  not regression  confides her wish to change and accepts his task to investigate shiraishi  is startled by morishita s  ear gun   blowing in her ear  which oddly helps ease her tension  is asked to investigate her","h":"<article class=\"card\" id=\"sc-yamamura-miki-y3v2-p157-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yamamura-miki.html#sc-yamamura-miki-y3v2-p157-1\">Year 3, Vol. 2 Ch.5 — depth read: Yamamura&#x27;s courage to change<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/yamamura-miki.html\">Yamamura Miki<\/a><\/span><\/h3><p class=\"setup\">Appears silently outside the south entrance after leading them on a change of meeting place.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/morishita-ai.html\">Morishita Ai<\/a> · <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Yamamura Miki<\/b> &quot;S-Sorry.&quot;<span class=\"pg\">p.157<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yamamura Miki<\/b> &quot;Y... Yes. Since you transferred classes, Ayanokouji-kun, we still... haven&#x27;t said a single word to each other... so...&quot;<span class=\"pg\">p.157<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Yamamura Miki<\/b> &quot;I want to change. I want to have more self-confidence, to be able to smile in front of others.&quot;<span class=\"pg\">p.161<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Please let me... help with getting to Class A, too.&quot;<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I want to do more... much more. Because I believe... there&#x27;s something... that only I can do.&quot;<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Yes... If you&#x27;re okay with it, Ayanokouji-kun, I think I can... try to investigate Shiraishi-san in my own way.&quot;<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Extremely shy and passive, but mustering real courage to voice her desire to change; Ayanokōji sees it as evolution, not regression.<span class=\"pg\">p.157–161<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Confides her wish to change and accepts his task to investigate Shiraishi.<span class=\"pg\">p.157–163<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morishita Ai<\/b> Is startled by Morishita&#x27;s &quot;Ear Gun&quot; (blowing in her ear), which oddly helps ease her tension.<span class=\"pg\">p.158–159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Is asked to investigate her.<span class=\"pg\">p.162<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-hashimoto-masayoshi-y3v2-p164-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka morishita-ai yamamura-miki hashimoto-masayoshi","q":"hashimoto masayoshi year 3  vol  2 ch 5   depth read  hashimoto s declaration of loyalty tracks ayanokoji and morishita down at the south entrance by process of elimination   kinda cold  isn t it  not inviting me to what looks like a pretty important chat   are you making yamamura your aide  ayanokouji   am i really that untrustworthy   i ve decided this class can win  the fact that i threw away my private points is proof of that   i m gonna keep pestering you anyway  persistent and self aware   knows his classmates distrust him  but has committed fully to class c  sacrificing his escape funds as proof  declares his loyalty and reasons for staying  is repeatedly rebuffed by her  calls her  miki chan  drawing a rebuke","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y3v2-p164-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hashimoto-masayoshi.html#sc-hashimoto-masayoshi-y3v2-p164-1\">Year 3, Vol. 2 Ch.5 — depth read: Hashimoto&#x27;s declaration of loyalty<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/span><\/h3><p class=\"setup\">Tracks Ayanokōji and Morishita down at the south entrance by process of elimination.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/morishita-ai.html\">Morishita Ai<\/a> · <a href=\"../../../people/yamamura-miki.html\">Yamamura Miki<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Kinda cold, isn&#x27;t it? Not inviting me to what looks like a pretty important chat.&quot;<span class=\"pg\">p.164<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Are you making Yamamura your aide, Ayanokouji?&quot;<span class=\"pg\">p.165<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> &quot;Am I really that untrustworthy?&quot;<span class=\"pg\">p.166<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;ve decided this class can win. The fact that I threw away my Private Points is proof of that.&quot;<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;m gonna keep pestering you anyway.&quot;<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Persistent and self-aware — knows his classmates distrust him, but has committed fully to Class C, sacrificing his escape funds as proof.<span class=\"pg\">p.164–167<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Declares his loyalty and reasons for staying.<span class=\"pg\">p.164–167<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morishita Ai<\/b> Is repeatedly rebuffed by her.<span class=\"pg\">p.164–165<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamamura Miki<\/b> Calls her &quot;Miki-chan,&quot; drawing a rebuke.<span class=\"pg\">p.165<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y3v2-p127-1\">← Before: Year 3, Vol. 2 Ch.4 — depth read: Hashimoto&#x27;s intel and Ike&#x27;s anger<\/button><\/div><\/article>"},{"i":"sc-hasebe-haruka-y3v2-p169-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka sakura-airi hasebe-haruka","q":"hasebe haruka year 3  vol  2 ch 5   depth read  hasebe s guilt and sakura s success appears in the hallway to the library and hesitantly asks to talk to ayanokoji   i  i wanted to talk for a bit  if that s  okay   you remembered   could that be my fault  because i came to talk to you and you got sick of it   with you changing classes  ayanokouji kun  i feel like we ve found a more appropriate distance between us   i just really wanted you  ayanokouji kun  to see how hard she s been working  nervous but resolute   feared she caused his transfer  then wanted to show him the expelled sakura s success  is reassured the transfer was unrelated  tells him about sakura  reveals the expelled sakura is now appearing on late night tv after passing an audition","h":"<article class=\"card\" id=\"sc-hasebe-haruka-y3v2-p169-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hasebe-haruka.html#sc-hasebe-haruka-y3v2-p169-1\">Year 3, Vol. 2 Ch.5 — depth read: Hasebe&#x27;s guilt and Sakura&#x27;s success<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/hasebe-haruka.html\">Hasebe Haruka<\/a><\/span><\/h3><p class=\"setup\">Appears in the hallway to the library and hesitantly asks to talk to Ayanokōji.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/sakura-airi.html\">Sakura Airi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hasebe Haruka<\/b> &quot;I... I wanted to talk for a bit, if that&#x27;s... okay?&quot;<span class=\"pg\">p.170<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hasebe Haruka<\/b> &quot;You remembered.&quot;<span class=\"pg\">p.172<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hasebe Haruka<\/b> &quot;Could that be my fault? Because I came to talk to you—and you got sick of it?&quot;<span class=\"pg\">p.172<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;With you changing classes, Ayanokouji-kun, I feel like we&#x27;ve found a more appropriate distance between us.&quot;<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I just really wanted you, Ayanokouji-kun, to see how hard she&#x27;s been working—&quot;<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Nervous but resolute — feared she caused his transfer, then wanted to show him the expelled Sakura&#x27;s success.<span class=\"pg\">p.170–174<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is reassured the transfer was unrelated; tells him about Sakura.<span class=\"pg\">p.170–174<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakura Airi<\/b> Reveals the expelled Sakura is now appearing on late-night TV after passing an audition.<span class=\"pg\">p.173<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-kaneda-satoru-y3v2-p175-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"shiina-hiyori ryuuen-kakeru ishizaki-daichi hashimoto-masayoshi kaneda-satoru","q":"kaneda satoru year 3  vol  2 ch 5   depth read  kaneda s early arrival arrives 20 minutes early to the karaoke parlor  hoping to catch shiina alone   t thank you for coming today  shiina shi   i have regular meetings with ryuuen shi  so i would appreciate it if you didn t lump us together   no  i have not    reporting hashimoto has ignored his messages since the transfer nervous and reserved around shiina  sharp with ishizaki  objectively revises his evaluation of ayanokoji but rates him below ryuen sakayanagi  arrives early hoping to spend time with her  calls her  shiina shi  reports to him and has regular one on one meetings  is needled by him for arriving early to see shiina  notes he stopped replying after ayanokoji s transfer","h":"<article class=\"card\" id=\"sc-kaneda-satoru-y3v2-p175-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kaneda-satoru.html#sc-kaneda-satoru-y3v2-p175-1\">Year 3, Vol. 2 Ch.5 — depth read: Kaneda&#x27;s early arrival<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/kaneda-satoru.html\">Kaneda Satoru<\/a><\/span><\/h3><p class=\"setup\">Arrives 20 minutes early to the karaoke parlor, hoping to catch Shiina alone.<\/p><p class=\"with\">with <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kaneda Satoru<\/b> &quot;T-Thank you for coming today, Shiina-shi.&quot;<span class=\"pg\">p.175<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kaneda Satoru<\/b> &quot;I have regular meetings with Ryuuen-shi, so I would appreciate it if you didn&#x27;t lump us together.&quot;<span class=\"pg\">p.176<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kaneda Satoru<\/b> &quot;No, I have not.&quot; — reporting Hashimoto has ignored his messages since the transfer<span class=\"pg\">p.177<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Nervous and reserved around Shiina, sharp with Ishizaki; objectively revises his evaluation of Ayanokōji but rates him below Ryūen/Sakayanagi.<span class=\"pg\">p.175–177<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> Arrives early hoping to spend time with her; calls her &quot;Shiina-shi.&quot;<span class=\"pg\">p.175<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Reports to him and has regular one-on-one meetings.<span class=\"pg\">p.176–177<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Is needled by him for arriving early to see Shiina.<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Notes he stopped replying after Ayanokōji&#x27;s transfer.<span class=\"pg\">p.177<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kaneda-satoru-y3v2-p195-1\">→ After: Year 3, Vol. 2 Ch.6 — depth read: Kaneda&#x27;s envy and probe<\/button><\/div><\/article>"},{"i":"sc-shiina-hiyori-y3v2-p175-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ryuuen-kakeru ayanokouji-kiyotaka ishizaki-daichi kaneda-satoru shiina-hiyori","q":"shiina hiyori year 3  vol  2 ch 5   depth read  shiina under ryuen s scrutiny arrives early to meet kaneda at the karaoke parlor  joins ryuen s strategy meeting   i wonder  i can t really give a good answer   no  actually  i haven t been able to speak with him properly yet  sees ayanokoji through a  filter   ishizaki s term  still hasn t spoken to him since his transfer and is sinking under her unresolved feelings  is told he ll make her useful to the class  not to ayanokoji   exploiting her feelings  has not spoken to him since his transfer  her feelings have become  heavy shackles  he calls her bias the  ayanokouji filter  meets him early at the parlor","h":"<article class=\"card\" id=\"sc-shiina-hiyori-y3v2-p175-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiina-hiyori.html#sc-shiina-hiyori-y3v2-p175-1\">Year 3, Vol. 2 Ch.5 — depth read: Shiina under Ryūen&#x27;s scrutiny<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a><\/span><\/h3><p class=\"setup\">Arrives early to meet Kaneda at the karaoke parlor; joins Ryūen&#x27;s strategy meeting.<\/p><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"../../../people/kaneda-satoru.html\">Kaneda Satoru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> &quot;I wonder... I can&#x27;t really give a good answer.&quot;<span class=\"pg\">p.178<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> &quot;No... Actually, I haven&#x27;t been able to speak with him properly yet.&quot;<span class=\"pg\">p.178<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Sees Ayanokōji through a &quot;filter&quot; (Ishizaki&#x27;s term); still hasn&#x27;t spoken to him since his transfer and is sinking under her unresolved feelings.<span class=\"pg\">p.178, 181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Is told he&#x27;ll make her useful to the class, not to Ayanokōji — exploiting her feelings.<span class=\"pg\">p.178, 181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Has not spoken to him since his transfer; her feelings have become &quot;heavy shackles.&quot;<span class=\"pg\">p.178–181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> He calls her bias the &quot;Ayanokouji Filter.&quot;<span class=\"pg\">p.178<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kaneda Satoru<\/b> Meets him early at the parlor.<span class=\"pg\">p.175<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiina-hiyori-y3v2-p190-1\">→ After: Year 3, Vol. 2 Ch.6 — depth read: Hiyori avoids, then opens up<\/button><\/div><\/article>"},{"i":"sc-ryuuen-kakeru-y3v2-p177-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"shiina-hiyori kaneda-satoru katsuragi-kouhei hashimoto-masayoshi ryuuen-kakeru","q":"ryuen kakeru year 3  vol  2 ch 5   depth read  ryuen s class prepares  so he s made up his mind  huh   if he makes a clumsy move to secure his own escape route  he ll be cut off without mercy   i don t give a damn what kind of feelings you have for ayanokouji  but as long as you re a member of my class  you need to work to make us win   tearing down ayanokouji and the next special exam  figured i d touch on that   fouls  whatever  i ll use any means necessary to win   i ll make damn sure you re useful  not for ayanokouji  but for this class  ruthless and pragmatic   rates ayanokoji highly  plans to exploit any means  including shiina s feelings  to defeat him  presses her for her read on ayanokoji and resolves to use her feelings for the class  notes hashimoto has stopped contacting him   proof of his commitment to ayanokoji  clashes with him over fighting dirty vs  by the rules  interprets his silence as a decision to commit fully","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y3v2-p177-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y3v2-p177-1\">Year 3, Vol. 2 Ch.5 — depth read: Ryūen&#x27;s class prepares<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a> · <a href=\"../../../people/kaneda-satoru.html\">Kaneda Satoru<\/a> · <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;So he&#x27;s made up his mind, huh?&quot;<span class=\"pg\">p.177<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;If he makes a clumsy move to secure his own escape route, he&#x27;ll be cut off without mercy.&quot;<span class=\"pg\">p.177<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> &quot;I don&#x27;t give a damn what kind of feelings you have for Ayanokouji. But as long as you&#x27;re a member of my class, you need to work to make us win.&quot;<span class=\"pg\">p.178<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Tearing down Ayanokouji and the next special exam. Figured I&#x27;d touch on that.&quot;<span class=\"pg\">p.179<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Fouls, whatever, I&#x27;ll use any means necessary to win.&quot;<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;ll make damn sure you&#x27;re useful. Not for Ayanokouji, but for this class.&quot;<span class=\"pg\">p.181<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Ruthless and pragmatic — rates Ayanokōji highly, plans to exploit any means (including Shiina&#x27;s feelings) to defeat him.<span class=\"pg\">p.177–181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> Presses her for her read on Ayanokōji and resolves to use her feelings for the class.<span class=\"pg\">p.178, 181<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kaneda Satoru<\/b> Notes Hashimoto has stopped contacting him — proof of his commitment to Ayanokōji.<span class=\"pg\">p.177<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Clashes with him over fighting dirty vs. by the rules.<span class=\"pg\">p.180<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Interprets his silence as a decision to commit fully.<span class=\"pg\">p.177<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-morishita-ai-y3v2-p182-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka morishita-ai","q":"morishita ai year 3  vol  2 ch 6   depth read  morishita s rubber band gun fires a rubber band at ayanokoji from a gun made of disposable chopsticks   to think you re still alive  you re quite something   it is a gun  a gun   that s because i m shooting you with the intent to cause pain   a face as hideously distorted as yours  ayanokouji kiyotaka  is better at least it warrants pity   for no reason other than i m simply not interested    refusing satonaka s invitation eccentric and violent playful   crafted a  lethal  rubber band gun during break  targets only ayanokoji  and teases him about having feelings  shoots him with rubber bands and needles him  turns down satonaka s group invitation bluntly  teases ayanokoji about having feelings for him","h":"<article class=\"card\" id=\"sc-morishita-ai-y3v2-p182-1\"><h3><span class=\"ttl\"><a href=\"../../../people/morishita-ai.html#sc-morishita-ai-y3v2-p182-1\">Year 3, Vol. 2 Ch.6 — depth read: Morishita&#x27;s rubber-band gun<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/morishita-ai.html\">Morishita Ai<\/a><\/span><\/h3><p class=\"setup\">Fires a rubber band at Ayanokōji from a gun made of disposable chopsticks.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;To think you&#x27;re still alive. You&#x27;re quite something.&quot;<span class=\"pg\">p.182<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;It is a gun. A gun.&quot;<span class=\"pg\">p.183<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Morishita Ai<\/b> &quot;That&#x27;s because I&#x27;m shooting you with the intent to cause pain.&quot;<span class=\"pg\">p.183<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;A face as hideously distorted as yours, Ayanokouji Kiyotaka, is better—at least it warrants pity.&quot;<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;For no reason other than I&#x27;m simply not interested.&quot; — refusing Satonaka&#x27;s invitation<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Eccentric and violent-playful — crafted a &quot;lethal&quot; rubber-band gun during break, targets only Ayanokōji, and teases him about having feelings.<span class=\"pg\">p.182–184<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Shoots him with rubber bands and needles him.<span class=\"pg\">p.182–184<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Turns down Satonaka&#x27;s group invitation bluntly; teases Ayanokōji about having feelings for him.<span class=\"pg\">p.183–184<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-morishita-ai-y3v2-p152-1\">← Before: Year 3, Vol. 2 Ch.5 — depth read: Morishita&#x27;s comic manipulation<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y3v2-p185-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka ichinose-honami chabashira-sae hoshinomiya-chie","q":"hoshinomiya chie year 3  vol  2 ch 6   depth read  hoshinomiya s boundary test meets ayanokoji in the special building  both claim the other was called by ichinose  presses against him   whaaat are you talking about  a teacher would never call a student out to a place like this   i need you to do your best this year  ayanokouji kun  so it s fine if i give you a little bit of service  right   we re in this together  aren t we  so there s no way i d do anything to drag you down  right   you just have to arrange things so my class takes first and your class takes second   i can trust you  right    a veiled threat if betrayed playful and flirtatious on the surface  still desperate to return her class to class a and see chabashira fall  tests ayanokoji and demands results  tests him physically to probe the exam  wants him to make her class win  her class is allied with ayanokoji s  rival  wants her class to fall","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y3v2-p185-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hoshinomiya-chie.html#sc-hoshinomiya-chie-y3v2-p185-1\">Year 3, Vol. 2 Ch.6 — depth read: Hoshinomiya&#x27;s boundary test<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/hoshinomiya-chie.html\">Hoshinomiya Chie<\/a><\/span><\/h3><p class=\"setup\">Meets Ayanokōji in the special building (both claim the other was called by Ichinose); presses against him.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hoshinomiya Chie<\/b> &quot;Whaaat are you talking about~? A teacher would never call a student out to a place like this.&quot;<span class=\"pg\">p.185<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hoshinomiya Chie<\/b> &quot;I need you to do your best this year, Ayanokouji-kun, so it&#x27;s fine if I give you a little bit of service, right?&quot;<span class=\"pg\">p.186<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hoshinomiya Chie<\/b> &quot;We&#x27;re in this together, aren&#x27;t we? So there&#x27;s no way I&#x27;d do anything to drag you down, right?&quot;<span class=\"pg\">p.188<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;You just have to arrange things so my class takes first and your class takes second.&quot;<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I can trust you, right?&quot; — a veiled threat if betrayed<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Playful and flirtatious on the surface, still desperate to return her class to Class A and see Chabashira fall; tests Ayanokōji and demands results.<span class=\"pg\">p.185–189<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Tests him physically to probe the exam; wants him to make her class win.<span class=\"pg\">p.184–189<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Her class is allied with Ayanokōji&#x27;s.<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Chabashira Sae<\/b> Rival; wants her class to fall.<span class=\"pg\">p.189<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v2-p186-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"hoshinomiya-chie shiina-hiyori kaneda-satoru morishita-ai ayanokouji-kiyotaka","q":"ayanokoji kiyotaka year 3  vol  2 ch 6   depth read  hoshinomiya s test and hiyori  you leave no openings  do you  hoshinomiya sensei   what the school will judge over the course of one week is our  attitude in our daily school life   isn t it also necessary to believe in your own class   remember to watch over them  that s something even chabashira sensei is capable of   no  i came to see you today  hiyori   if you don t mind  hiyori  why don t we talk about this past month we ve been apart   envy me  i m a traitor who abandoned class a  uses hoshinomiya s deliberate physical advance to confirm the exam judges daily conduct via security camera recordings  admits hiyori is  a little different from the frameworks  he used   simply reading and sharing space with her gives him a sense of  happiness  meets her  stops her interference by invoking the alliance and chabashira  finally visits her  apologizes  talks for hours  and realizes his feelings for her may be more than friendship  talks with him in the library  is praised and envied  and questioned about hiyori  is shot repeatedly with her rubber band gun","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v2-p186-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v2-p186-1\">Year 3, Vol. 2 Ch.6 — depth read: Hoshinomiya&#x27;s test and Hiyori<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/hoshinomiya-chie.html\">Hoshinomiya Chie<\/a> · <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a> · <a href=\"../../../people/kaneda-satoru.html\">Kaneda Satoru<\/a> · <a href=\"../../../people/morishita-ai.html\">Morishita Ai<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;You leave no openings, do you, Hoshinomiya-sensei.&quot;<span class=\"pg\">p.186<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;What the school will judge over the course of one week is our &#x27;attitude in our daily school life.&#x27;&quot;<span class=\"pg\">p.186<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Isn&#x27;t it also necessary to believe in your own class?&quot;<span class=\"pg\">p.188<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Remember to watch over them. That&#x27;s something even Chabashira-sensei is capable of.&quot;<span class=\"pg\">p.189<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;No, I came to see you today, Hiyori.&quot;<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If you don&#x27;t mind, Hiyori, why don&#x27;t we talk about this past month we&#x27;ve been apart?&quot;<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Envy me? I&#x27;m a traitor who abandoned Class A.&quot;<span class=\"pg\">p.198<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Uses Hoshinomiya&#x27;s deliberate physical advance to confirm the exam judges daily conduct via security-camera recordings.<span class=\"pg\">p.186<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Admits Hiyori is &quot;a little different from the frameworks&quot; he used — simply reading and sharing space with her gives him a sense of &quot;happiness.&quot;<span class=\"pg\">p.201<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hoshinomiya Chie<\/b> Meets her; stops her interference by invoking the alliance and Chabashira.<span class=\"pg\">p.184–189<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> Finally visits her, apologizes, talks for hours, and realizes his feelings for her may be more than friendship.<span class=\"pg\">p.190–202<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kaneda Satoru<\/b> Talks with him in the library; is praised and envied, and questioned about Hiyori.<span class=\"pg\">p.195–200<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morishita Ai<\/b> Is shot repeatedly with her rubber-band gun.<span class=\"pg\">p.182–184<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v2-p152-1\">← Before: Year 3, Vol. 2 Ch.5 — depth read: Yamamura, Hasebe and his own avoidance<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v2-p212-1\">→ After: Year 3, Vol. 2 Ch.7 — depth read: results, the gym plan and a new emotion<\/button><\/div><\/article>"},{"i":"sc-shiina-hiyori-y3v2-p190-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka kaneda-satoru shiina-hiyori","q":"shiina hiyori year 3  vol  2 ch 6   depth read  hiyori avoids  then opens up is in the mystery novel section of the library  repeatedly hides from ayanokoji when their eyes meet   did you come here to look for a book to read   the class transfer  how should i put it  was just me getting my hopes up on my own   i thought that our relationship  where we could chat so familiarly  had to come to an end   yes  in fact  i just finished reading another one last night   ever since i became a third year  kaneda kun has been visiting me often at this time   is it  really okay    agreeing to talk about the past month shy and hurt after his rejection  had tried to resolve to see him as an enemy  but his visit makes her smile for the first time that day  avoids him at first  then reconciles and spends hours reading and talking with him  has grown close to him   he now visits her often in the library","h":"<article class=\"card\" id=\"sc-shiina-hiyori-y3v2-p190-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiina-hiyori.html#sc-shiina-hiyori-y3v2-p190-1\">Year 3, Vol. 2 Ch.6 — depth read: Hiyori avoids, then opens up<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a><\/span><\/h3><p class=\"setup\">Is in the mystery-novel section of the library; repeatedly hides from Ayanokōji when their eyes meet.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/kaneda-satoru.html\">Kaneda Satoru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> &quot;Did you come here to look for a book to read...?&quot;<span class=\"pg\">p.191<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> &quot;The class transfer... how should I put it... was just me getting my hopes up on my own...&quot;<span class=\"pg\">p.194<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> &quot;I thought that our relationship, where we could chat so familiarly, had to come to an end.&quot;<span class=\"pg\">p.194<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Yes. In fact, I just finished reading another one last night.&quot;<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Ever since I became a third-year, Kaneda-kun has been visiting me often at this time.&quot;<span class=\"pg\">p.195<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Is it... really okay?&quot; — agreeing to talk about the past month<span class=\"pg\">p.194<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Shy and hurt after his rejection; had tried to resolve to see him as an enemy, but his visit makes her smile for the first time that day.<span class=\"pg\">p.190–194<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Avoids him at first, then reconciles and spends hours reading and talking with him.<span class=\"pg\">p.190–202<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kaneda Satoru<\/b> Has grown close to him — he now visits her often in the library.<span class=\"pg\">p.195<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiina-hiyori-y3v2-p175-1\">← Before: Year 3, Vol. 2 Ch.5 — depth read: Shiina under Ryūen&#x27;s scrutiny<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-shiina-hiyori-y3v2-p253-1\">→ After: Year 3, Vol. 2 SS: A Wavering Heart — depth read<\/button><\/div><\/article>"},{"i":"sc-kaneda-satoru-y3v2-p195-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka shiina-hiyori kaneda-satoru","q":"kaneda satoru year 3  vol  2 ch 6   depth read  kaneda s envy and probe arrives at the library to visit hiyori  finds ayanokoji with her and joins their table   i m not very good at such meaningless small talk   it was the first time in a long while i d seen her genuine smile   you re the very picture of a hero  are you not  i envy you from the bottom of my heart   even that part of you is so cool it s infuriating  ayanokouji shi   then  what if that person were shiina shi  eloquent and passionate but self deprecating   heaps praise on ayanokoji while belittling himself  and envies him deeply  dislikes but is fascinated by him  envies him as a  hero  disparages himself  and probes what if hiyori hated him  leaves abruptly  is a frequent library visitor to see her  has feelings for her and was surprised by her genuine smile","h":"<article class=\"card\" id=\"sc-kaneda-satoru-y3v2-p195-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kaneda-satoru.html#sc-kaneda-satoru-y3v2-p195-1\">Year 3, Vol. 2 Ch.6 — depth read: Kaneda&#x27;s envy and probe<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/kaneda-satoru.html\">Kaneda Satoru<\/a><\/span><\/h3><p class=\"setup\">Arrives at the library to visit Hiyori; finds Ayanokōji with her and joins their table.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kaneda Satoru<\/b> &quot;I&#x27;m not very good at such meaningless small talk.&quot;<span class=\"pg\">p.196<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kaneda Satoru<\/b> &quot;It was the first time in a long while I&#x27;d seen her genuine smile.&quot;<span class=\"pg\">p.197<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kaneda Satoru<\/b> &quot;You&#x27;re the very picture of a hero, are you not? I envy you from the bottom of my heart.&quot;<span class=\"pg\">p.198<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Even that part of you is so cool it&#x27;s infuriating, Ayanokouji-shi.&quot;<span class=\"pg\">p.199<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Then, what if that person were Shiina-shi...?&quot;<span class=\"pg\">p.199<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Eloquent and passionate but self-deprecating — heaps praise on Ayanokōji while belittling himself, and envies him deeply; dislikes but is fascinated by him.<span class=\"pg\">p.196–199<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Envies him as a &quot;hero,&quot; disparages himself, and probes what if Hiyori hated him; leaves abruptly.<span class=\"pg\">p.196–200<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> Is a frequent library visitor to see her; has feelings for her and was surprised by her genuine smile.<span class=\"pg\">p.195–200<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-kaneda-satoru-y3v2-p175-1\">← Before: Year 3, Vol. 2 Ch.5 — depth read: Kaneda&#x27;s early arrival<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y3v2-p212-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ichinose-honami shiina-hiyori watanabe-norihito nanase-tsubasa ayanokouji-kiyotaka","q":"ayanokoji kiyotaka year 3  vol  2 ch 7   depth read  results  the gym plan and a new emotion  i don t think it s a concern with this class  but make sure to tell everyone not to slander the two who are absent under any circumstances   letting her know you like her is also a valid strategy  you know   kanzaki and himeno  then hamaguchi  should be okay with these three  right   i intended to use kanzaki and the others to bring about a change in ichinose   it s not a problem in the grand scheme of things  it s a gap we can close if we aim to win the next special exam   the three i m thinking of asking are watanabe  kanzaki  and himeno  class c places last  25  due to two absentees  no ranking change overall  questions whether the emotion he felt during the library scene with hiyori is romance   a new  blissful feeling he clearly desires to repeat  coaches watanabe s romance tactically  plans to use the gym to elevate ichinose s class  kanzaki  himeno  watanabe  amikura  walk home  asks her to invite students to the gym  their hands touch and she apologizes for wanting to touch him  recalls the library moment and flower as his  blissful  memory  advises him on approaching amikura  not on friendly terms  she appears at the gym","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y3v2-p212-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y3v2-p212-1\">Year 3, Vol. 2 Ch.7 — depth read: results, the gym plan and a new emotion<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a> · <a href=\"../../../people/watanabe-norihito.html\">Watanabe Norihito<\/a> · <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;I don&#x27;t think it&#x27;s a concern with this class, but make sure to tell everyone not to slander the two who are absent under any circumstances.&quot;<span class=\"pg\">p.212<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Letting her know you like her is also a valid strategy, you know.&quot;<span class=\"pg\">p.214<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> &quot;Kanzaki and Himeno. Then Hamaguchi. Should be okay with these three, right?&quot;<span class=\"pg\">p.215<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I intended to use Kanzaki and the others to bring about a change in Ichinose.&quot;<span class=\"pg\">p.216<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;It&#x27;s not a problem in the grand scheme of things. It&#x27;s a gap we can close if we aim to win the next special exam.&quot;<span class=\"pg\">p.221<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;The three I&#x27;m thinking of asking are Watanabe, Kanzaki, and Himeno.&quot;<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Class C places last (−25) due to two absentees; no ranking change overall.<span class=\"pg\">p.221<\/span><\/li><li><span class=\"mlabel\">Inference, not stated<\/span> Questions whether the emotion he felt during the library scene with Hiyori is romance — a new, blissful feeling he clearly desires to repeat.<span class=\"pg\">p.224<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Coaches Watanabe&#x27;s romance tactically; plans to use the gym to elevate Ichinose&#x27;s class (Kanzaki, Himeno, Watanabe, Amikura).<span class=\"pg\">p.213–216<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Walk home; asks her to invite students to the gym; their hands touch and she apologizes for wanting to touch him.<span class=\"pg\">p.220–225<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> Recalls the library moment and flower as his &quot;blissful&quot; memory.<span class=\"pg\">p.224<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Watanabe Norihito<\/b> Advises him on approaching Amikura.<span class=\"pg\">p.213–216<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> Not on friendly terms; she appears at the gym.<span class=\"pg\">p.216–217<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y3v2-p186-1\">← Before: Year 3, Vol. 2 Ch.6 — depth read: Hoshinomiya&#x27;s test and Hiyori<\/button><\/div><\/article>"},{"i":"sc-watanabe-norihito-y3v2-p213-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka amikura-mako shibata-sou watanabe-norihito","q":"watanabe norihito year 3  vol  2 ch 7   depth read  watanabe s romantic nerves paces in front of the gym at keyaki mall  wanting to join to be near amikura but hesitant   wh whoa  ayanokouji  h hey  long time no see   i was just thinkin  about maybe joinin  the gym  y know   seriously  i can t have amikura finding out at this stage   if shibata saw you and ichinose together  he d cry   o oh  thanks  ayanokouji  you re a good guy  you know that  bashful and lovesick   wants to join the gym to spend time with amikura but fears being found out  compares him to a level one game hero  is coached by him on approaching amikura and the gym plan  wants to join the gym to get closer to her  mako chan  rules him out as a gym recruit  calling him a potential rival","h":"<article class=\"card\" id=\"sc-watanabe-norihito-y3v2-p213-1\"><h3><span class=\"ttl\"><a href=\"../../../people/watanabe-norihito.html#sc-watanabe-norihito-y3v2-p213-1\">Year 3, Vol. 2 Ch.7 — depth read: Watanabe&#x27;s romantic nerves<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/watanabe-norihito.html\">Watanabe Norihito<\/a><\/span><\/h3><p class=\"setup\">Paces in front of the gym at Keyaki Mall, wanting to join to be near Amikura but hesitant.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a> · <a href=\"../../../people/shibata-sou.html\">Shibata Sō<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Watanabe Norihito<\/b> &quot;Wh-whoa, Ayanokouji!? H-hey, long time no see.&quot;<span class=\"pg\">p.213<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Watanabe Norihito<\/b> &quot;I was just thinkin&#x27; about maybe joinin&#x27; the gym, y&#x27;know?&quot;<span class=\"pg\">p.213<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Watanabe Norihito<\/b> &quot;Seriously, I can&#x27;t have Amikura finding out at this stage!&quot;<span class=\"pg\">p.214<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;If Shibata saw you and Ichinose together, he&#x27;d cry...&quot;<span class=\"pg\">p.215<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;O-oh. Thanks, Ayanokouji. You&#x27;re a good guy, you know that?&quot;<span class=\"pg\">p.216<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Bashful and lovesick — wants to join the gym to spend time with Amikura but fears being found out; compares him to a level-one game hero.<span class=\"pg\">p.213–216<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is coached by him on approaching Amikura and the gym plan.<span class=\"pg\">p.213–216<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amikura Mako<\/b> Wants to join the gym to get closer to her (&quot;Mako-chan&quot;).<span class=\"pg\">p.213–215<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shibata Sō<\/b> Rules him out as a gym recruit, calling him a potential rival.<span class=\"pg\">p.215<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-akiyama-y3v2-p217-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka utomiya-riku mashima-tomonari akiyama","q":"akiyama year 3  vol  2 ch 7   depth read  akiyama s gym gossip passing by the gym  asks ayanokoji about his tense exchange with utomiya   that was utomiya kun  right  are you two on bad terms   there s a first year girl who was brought here by utomiya kun and joined recently   she was maintaining a 20 kilometer pace for several minutes   perhaps a storm of love is brewing   is my impression of him the right one  it s not like he s actually a player  is it  friendly and chatty   follows gym gossip  notes a remarkably talented first year and wonders about mashima  chats with him at the gym about utomiya and mashima  saw him at the gym looking at a first year girl  asks ayanokoji whether he is  a player","h":"<article class=\"card\" id=\"sc-akiyama-y3v2-p217-1\"><h3><span class=\"ttl\"><a href=\"../../../people/akiyama.html#sc-akiyama-y3v2-p217-1\">Year 3, Vol. 2 Ch.7 — depth read: Akiyama&#x27;s gym gossip<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/akiyama.html\">Akiyama<\/a><\/span><\/h3><p class=\"setup\">Passing by the gym, asks Ayanokōji about his tense exchange with Utomiya.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/utomiya-riku.html\">Utomiya Riku<\/a> · <a href=\"../../../people/mashima-tomonari.html\">Mashima Tomonari<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Akiyama<\/b> &quot;That was Utomiya-kun, right? Are you two on bad terms?&quot;<span class=\"pg\">p.217<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Akiyama<\/b> &quot;There&#x27;s a first-year girl who was brought here by Utomiya-kun and joined recently.&quot;<span class=\"pg\">p.218<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Akiyama<\/b> &quot;She was maintaining a 20-kilometer pace for several minutes.&quot;<span class=\"pg\">p.218<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Perhaps a storm of love is brewing.&quot;<span class=\"pg\">p.218<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Is my impression of him the right one? It&#x27;s not like he&#x27;s actually a player, is it?&quot;<span class=\"pg\">p.219<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Friendly and chatty — follows gym gossip, notes a remarkably talented first-year and wonders about Mashima.<span class=\"pg\">p.217–219<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Chats with him at the gym about Utomiya and Mashima.<span class=\"pg\">p.217–219<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Utomiya Riku<\/b> Saw him at the gym looking at a first-year girl.<span class=\"pg\">p.217<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mashima Tomonari<\/b> Asks Ayanokōji whether he is &quot;a player.&quot;<span class=\"pg\">p.219<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ichinose-honami-y3v2-p220-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka amikura-mako watanabe-norihito ichinose-honami","q":"ichinose honami year 3  vol  2 ch 7   depth read  ichinose sees through him  mm  i think she was just being considerate  so that you and i could talk alone  ayanokouji kun   i see  that s very reassuring  i ll do my best to help out as much as i can  too   i think that s a great idea  i was actually getting a little worried about things like sales  since the number of members is so low   that s an interesting trio  kanzaki kun has seemed a little distant from me lately   and watanabe kun simply wants to get closer to mako chan i guess that s about it  right   i i m sorry  i m sorry  i just  couldn t help wanting to touch you  even though we re just friends  aren t we   because you looked so happy  i suppose  sharp and perceptive   reads through ayanokoji s  natural  trio selection and senses he was thinking of someone else  her perception has sharpened since  that night  walks home with him  their hands touch and she apologizes  left with a lonely expression when he seems distracted  notes amikura left early to give them privacy  knows watanabe likes her  mako chan  agrees to welcome him to the gym","h":"<article class=\"card\" id=\"sc-ichinose-honami-y3v2-p220-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y3v2-p220-1\">Year 3, Vol. 2 Ch.7 — depth read: Ichinose sees through him<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/amikura-mako.html\">Amikura Mako<\/a> · <a href=\"../../../people/watanabe-norihito.html\">Watanabe Norihito<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> &quot;Mm, I think she was just being considerate. So that you and I could talk alone, Ayanokouji-kun.&quot;<span class=\"pg\">p.220<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> &quot;I see. That&#x27;s very reassuring. I&#x27;ll do my best to help out as much as I can, too.&quot;<span class=\"pg\">p.221<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> &quot;I think that&#x27;s a great idea! I was actually getting a little worried about things like sales, since the number of members is so low.&quot;<span class=\"pg\">p.221<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;That&#x27;s an interesting trio. Kanzaki-kun has seemed a little distant from me lately.&quot;<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;And Watanabe-kun simply wants to get closer to Mako-chan—I guess that&#x27;s about it, right?&quot;<span class=\"pg\">p.223<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I-I&#x27;m sorry... I&#x27;m sorry. I just... couldn&#x27;t help wanting to touch you... even though we&#x27;re just friends, aren&#x27;t we.&quot;<span class=\"pg\">p.224<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Because you looked so happy, I suppose.&quot;<span class=\"pg\">p.224<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Sharp and perceptive — reads through Ayanokōji&#x27;s &quot;natural&quot; trio selection and senses he was thinking of someone else; her perception has sharpened since &quot;that night.&quot;<span class=\"pg\">p.223–224<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Walks home with him; their hands touch and she apologizes, left with a lonely expression when he seems distracted.<span class=\"pg\">p.220–225<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amikura Mako<\/b> Notes Amikura left early to give them privacy; knows Watanabe likes her (&quot;Mako-chan&quot;).<span class=\"pg\">p.220<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Watanabe Norihito<\/b> Agrees to welcome him to the gym.<span class=\"pg\">p.221<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y3v2-p249-1\">→ After: Year 3, Vol. 2 SS: To Love Too Much… — depth read<\/button><\/div><\/article>"},{"i":"sc-nanase-tsubasa-y3v2-p226-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"shiraishi-asuka tsukishiro ayanokouji-kiyotaka nanase-tsubasa","q":"nanase tsubasa year 3  vol  2 ch 7   depth read  nanase works the white room angle meets shiraishi back to back in a quiet restaurant  having called her out   have i kept you waiting   why is that   then why have you started to close the distance now   i am from that side   at least give me some information  please  just disclose the names of your associates   that if i am expelled before ayanokouji senpai s fate is decided  things may very well head in a direction that shirogane sensei would not desire  cautious and probing   arranged a covert meeting  tries to read shiraishi through emphases and emphasized names  and aligns herself with tsukishiro s anti ayanokoji faction  demands her cooperation intelligence  is refused  and warns her of consequences if expelled  reveals she is aligned with his faction  that side superiors  is working against him  refers to him as  ayanokouji senpai  cites  shirogane sensei  in her warning   a name tied to her past  not on the roster","h":"<article class=\"card\" id=\"sc-nanase-tsubasa-y3v2-p226-1\"><h3><span class=\"ttl\"><a href=\"../../../people/nanase-tsubasa.html#sc-nanase-tsubasa-y3v2-p226-1\">Year 3, Vol. 2 Ch.7 — depth read: Nanase works the White Room angle<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/span><\/h3><p class=\"setup\">Meets Shiraishi back-to-back in a quiet restaurant, having called her out.<\/p><p class=\"with\">with <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a> · <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> &quot;Have I kept you waiting?&quot;<span class=\"pg\">p.226<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> &quot;Why...is that?&quot;<span class=\"pg\">p.228<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Nanase Tsubasa<\/b> &quot;Then why have you started to close the distance now?&quot;<span class=\"pg\">p.229<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I am from that side.&quot;<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;At least give me some information... Please, just disclose the names of your associates.&quot;<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;That if I am expelled before Ayanokouji-senpai&#x27;s fate is decided... things may very well head in a direction that Shirogane-sensei would not desire.&quot;<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Cautious and probing — arranged a covert meeting, tries to read Shiraishi through emphases and emphasized names, and aligns herself with Tsukishiro&#x27;s anti-Ayanokōji faction.<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Demands her cooperation/intelligence; is refused, and warns her of consequences if expelled.<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Reveals she is aligned with his faction (&quot;that side&quot;/&quot;superiors&quot;).<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is working against him; refers to him as &quot;Ayanokouji-senpai.&quot;<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Cites &quot;Shirogane-sensei&quot; in her warning — a name tied to her past (not on the roster).<span class=\"pg\">p.230<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-nanase-tsubasa-y3v2-p85-1\">← Before: Year 3, Vol. 2 Ch.3 — depth read: Nanase and the first-year fight<\/button><\/div><\/article>"},{"i":"sc-shiraishi-asuka-y3v2-p226-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"nanase-tsubasa ayanokouji-kiyotaka tsukishiro shiraishi-asuka","q":"shiraishi asuka year 3  vol  2 ch 7   depth read  shiraishi reveals herself as an observer meets nanase back to back at a quiet restaurant to avoid being seen together   how i procured that information is a trade secret   that s because i am  strictly speaking  an observer   from the very beginning  i was never given any role beyond that   through an ironic twist of fate  he and i ended up in the same class   all that is required of us is to spend three years as ordinary students   if you wish to know  i suggest you ask your superiors directly  tsukishiro san  was it  reveals she is a white room  observer    tasked only to live as an ordinary student for three years  her proximity to ayanokoji is coincidence she chooses to enjoy  calm and strategic   chose the covert meeting setup deliberately  sees through nanase s probes  and refuses to cooperate while reassuring her selectively  meets her secretly  refuses to provide intelligence  only reassures about hashimoto morishita  and warns of consequences if she is expelled  is his classmate and neighbor  enjoys the environment as an observer  names him as nanase s superior  does not like him  uses ayanokoji s own line  trade secret  back on him  per nanase s recollection","h":"<article class=\"card\" id=\"sc-shiraishi-asuka-y3v2-p226-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiraishi-asuka.html#sc-shiraishi-asuka-y3v2-p226-1\">Year 3, Vol. 2 Ch.7 — depth read: Shiraishi reveals herself as an observer<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/span><\/h3><p class=\"setup\">Meets Nanase back-to-back at a quiet restaurant to avoid being seen together.<\/p><p class=\"with\">with <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/tsukishiro.html\">Tsukishiro<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;How I procured that information is a trade secret.&quot;<span class=\"pg\">p.227<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;That&#x27;s because I am, strictly speaking, an observer.&quot;<span class=\"pg\">p.229<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiraishi Asuka<\/b> &quot;From the very beginning, I was never given any role beyond that.&quot;<span class=\"pg\">p.229<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Through an ironic twist of fate, he and I ended up in the same class.&quot;<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;All that is required of us is to spend three years as ordinary students.&quot;<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;If you wish to know, I suggest you ask your superiors directly. Tsukishiro-san, was it?&quot;<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Reveals she is a White Room &quot;observer&quot; — tasked only to live as an ordinary student for three years; her proximity to Ayanokōji is coincidence she chooses to enjoy.<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Calm and strategic — chose the covert meeting setup deliberately, sees through Nanase&#x27;s probes, and refuses to cooperate while reassuring her selectively.<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> Meets her secretly; refuses to provide intelligence, only reassures about Hashimoto/Morishita, and warns of consequences if she is expelled.<span class=\"pg\">p.226–230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is his classmate and neighbor; enjoys the environment as an observer.<span class=\"pg\">p.229<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Names him as Nanase&#x27;s superior; does not like him.<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Uses Ayanokōji&#x27;s own line (&quot;trade secret&quot;) back on him, per Nanase&#x27;s recollection.<span class=\"pg\">p.229<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiraishi-asuka-y3v2-p127-1\">← Before: Year 3, Vol. 2 Ch.4 — depth read: Shiraishi&#x27;s deliberate mystery<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y3v2-p231-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"karuizawa-kei ishigami-kyou amasawa-ichika nanase-tsubasa horikita-suzune","q":"horikita suzune year 3  vol  2 epilogue   depth read  investigating ayanokoji s past  good morning  i apologize for contacting you so suddenly last night   if that s what you were expecting  then i m afraid i ll have to apologize  i didn t invite you to hang out for fun   you re sharp  that is one of my objectives   but if it s something even you don t know  then i can give up   i have no intention of keeping secrets or telling you any clumsy lies  either   i m sorry  i know it s sudden  but i have to go to the student council  begins investigating ayanokoji s past   tails amasawa with karuizawa  then receives ishigami s lead that nanase is the one who knows his past  invites her out  they tail amasawa together  is approached by him  receives the lead about nanase and agrees to keep his identity secret  tails her as a possible link to ayanokoji s past  learns from ishigami that she may know ayanokoji s past  plans to investigate","h":"<article class=\"card\" id=\"sc-horikita-suzune-y3v2-p231-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y3v2-p231-1\">Year 3, Vol. 2 Epilogue — depth read: investigating Ayanokōji&#x27;s past<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a> · <a href=\"../../../people/ishigami-kyou.html\">Ishigami Kyō<\/a> · <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a> · <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;Good morning, I apologize for contacting you so suddenly last night.&quot;<span class=\"pg\">p.231<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;If that&#x27;s what you were expecting, then I&#x27;m afraid I&#x27;ll have to apologize. I didn&#x27;t invite you to hang out for fun.&quot;<span class=\"pg\">p.231<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> &quot;You&#x27;re sharp. That is one of my objectives.&quot;<span class=\"pg\">p.232<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;But if it&#x27;s something even you don&#x27;t know, then I can give up.&quot;<span class=\"pg\">p.232<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I have no intention of keeping secrets or telling you any clumsy lies, either.&quot;<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;m sorry. I know it&#x27;s sudden, but I have to go to the student council.&quot;<span class=\"pg\">p.237<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Begins investigating Ayanokōji&#x27;s past — tails Amasawa with Karuizawa, then receives Ishigami&#x27;s lead that Nanase is the one who knows his past.<span class=\"pg\">p.231–246<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Invites her out; they tail Amasawa together.<span class=\"pg\">p.231–237<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishigami Kyō<\/b> Is approached by him; receives the lead about Nanase and agrees to keep his identity secret.<span class=\"pg\">p.238–246<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> Tails her as a possible link to Ayanokōji&#x27;s past.<span class=\"pg\">p.235–236<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> Learns from Ishigami that she may know Ayanokōji&#x27;s past; plans to investigate.<span class=\"pg\">p.244–246<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y3v2-p67-1\">← Before: Year 3, Vol. 2 Ch.3 — depth read: Horikita&#x27;s leadership tested<\/button><\/div><\/article>"},{"i":"sc-karuizawa-kei-y3v2-p231-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"horikita-suzune ayanokouji-kiyotaka amasawa-ichika karuizawa-kei","q":"karuizawa kei year 3  vol  2 epilogue   depth read  karuizawa helps investigate  getting an invitation from you  horikita san  was kinda new and exciting  so i was happy   okay  then ask me anything  if it s something i know  i ll answer whatever   i was dating ayanokouji kun  but to be honest  i doubt i have much more information than you do   i tried asking him about his past a few times  but i don t think he ever really gave me a straight answer   ahh  so that s how it is   i don t mind doing spy like stuff  i mean  is there anyone who actually dislikes it   i won t go tailing amasawa san on my own  so don t you worry  warm and eager to help  enjoys the  spy  work but knows her limits  still careful about boundaries  first name slips  agrees to answer horikita s questions and tails amasawa with her  says he never gave straight answers about his past  sensed her relationship with ayanokoji was more than simple senpai kouhai","h":"<article class=\"card\" id=\"sc-karuizawa-kei-y3v2-p231-1\"><h3><span class=\"ttl\"><a href=\"../../../people/karuizawa-kei.html#sc-karuizawa-kei-y3v2-p231-1\">Year 3, Vol. 2 Epilogue — depth read: Karuizawa helps investigate<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> &quot;Getting an invitation from you, Horikita-san, was kinda new and exciting, so I was happy.&quot;<span class=\"pg\">p.231<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> &quot;Okay. Then ask me anything. If it&#x27;s something I know, I&#x27;ll answer whatever!&quot;<span class=\"pg\">p.232<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> &quot;I was dating Ayanokouji-kun, but to be honest, I doubt I have much more information than you do.&quot;<span class=\"pg\">p.234<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I tried asking him about his past a few times, but I don&#x27;t think he ever really gave me a straight answer.&quot;<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Ahh... So that&#x27;s how it is.&quot;<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I don&#x27;t mind doing spy-like stuff. I mean, is there anyone who actually dislikes it?&quot;<span class=\"pg\">p.235<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I won&#x27;t go tailing Amasawa-san on my own, so don&#x27;t you worry.&quot;<span class=\"pg\">p.237<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Warm and eager to help; enjoys the &quot;spy&quot; work but knows her limits; still careful about boundaries (first-name slips).<span class=\"pg\">p.231–237<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Agrees to answer Horikita&#x27;s questions and tails Amasawa with her.<span class=\"pg\">p.231–237<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Says he never gave straight answers about his past.<span class=\"pg\">p.234<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> Sensed her relationship with Ayanokōji was more than simple senpai/kouhai.<span class=\"pg\">p.235<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-karuizawa-kei-y3v2-p89-1\">← Before: Year 3, Vol. 2 Ch.3 — depth read: Karuizawa&#x27;s read on Ayanokōji<\/button><\/div><\/article>"},{"i":"sc-ishigami-kyou-y3v2-p238-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"horikita-suzune nanase-tsubasa ayanokouji-kiyotaka amasawa-ichika ishigami-kyou","q":"ishigami kyo year 3  vol  2 epilogue   depth read  ishigami s hidden lead stops horikita in the hallway on a holiday after luring her to the empty student council room   it s been a while  i have something i d like to discuss  so may i have a moment of your time   were you the one who sent me the message   regarding my consultation it seems you ve been looking into amasawa  president   you must absolutely keep the identity of the person who gave you this student s name in other words  me confidential   she s a female student from second year class d named nanase   i ve learned that nanase was in contact with ayanokouji senpai from very early on  secretly arranges the meeting  reveals nanase  not amasawa  as the one who knows ayanokoji s past  and agrees to probe anonymously  cautious and analytical   orchestrates a roundabout  unobserved meeting  pressures horikita to protect his anonymity  and only deals in his own class s affairs  gives her the nanase lead in exchange for anonymity  claims she knows ayanokoji s past and dislikes him  refers to him as  ayanokouji senpai  says nanase was in early contact with him  is in the same class  knew horikita was tailing her","h":"<article class=\"card\" id=\"sc-ishigami-kyou-y3v2-p238-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ishigami-kyou.html#sc-ishigami-kyou-y3v2-p238-1\">Year 3, Vol. 2 Epilogue — depth read: Ishigami&#x27;s hidden lead<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/ishigami-kyou.html\">Ishigami Kyō<\/a><\/span><\/h3><p class=\"setup\">Stops Horikita in the hallway on a holiday after luring her to the empty student council room.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/nanase-tsubasa.html\">Nanase Tsubasa<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/amasawa-ichika.html\">Amasawa Ichika<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ishigami Kyō<\/b> &quot;It&#x27;s been a while. I have something I&#x27;d like to discuss, so may I have a moment of your time?&quot;<span class=\"pg\">p.239<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ishigami Kyō<\/b> &quot;Were you the one who sent me the message?&quot;<span class=\"pg\">p.241<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ishigami Kyō<\/b> &quot;Regarding my consultation—it seems you&#x27;ve been looking into Amasawa, President.&quot;<span class=\"pg\">p.241<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;You must absolutely keep the identity of the person who gave you this student&#x27;s name—in other words, me—confidential.&quot;<span class=\"pg\">p.244<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;She&#x27;s a female student from second-year Class D named Nanase.&quot;<span class=\"pg\">p.244<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I&#x27;ve learned that Nanase was in contact with Ayanokouji-senpai from very early on.&quot;<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Secretly arranges the meeting, reveals Nanase (not Amasawa) as the one who knows Ayanokōji&#x27;s past, and agrees to probe anonymously.<span class=\"pg\">p.238–246<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Cautious and analytical — orchestrates a roundabout, unobserved meeting, pressures Horikita to protect his anonymity, and only deals in his own class&#x27;s affairs.<span class=\"pg\">p.239–246<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Gives her the Nanase lead in exchange for anonymity.<span class=\"pg\">p.238–246<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nanase Tsubasa<\/b> Claims she knows Ayanokōji&#x27;s past and dislikes him.<span class=\"pg\">p.244–246<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Refers to him as &quot;Ayanokouji-senpai&quot;; says Nanase was in early contact with him.<span class=\"pg\">p.245<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amasawa Ichika<\/b> Is in the same class; knew Horikita was tailing her.<span class=\"pg\">p.241<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ichinose-honami-y3v2-p249-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka ichinose-honami","q":"ichinose honami year 3  vol  2 ss  to love too much    depth read  okay  thank you  i m really happy for your support  ayanokouji kun   i i m sorry  i m sorry  i just  couldn t help wanting to touch you  even though we re just friends  aren t we  aches during the week apart without seeing him  yearns for his fingers and wonders how to make him yearn for her too    loving someone too much  is painful  their hands touch on the walk home  she pulls back  determined to stay on his level","h":"<article class=\"card\" id=\"sc-ichinose-honami-y3v2-p249-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y3v2-p249-1\">Year 3, Vol. 2 SS: To Love Too Much… — depth read<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> &quot;Okay, thank you. I&#x27;m really happy for your support, Ayanokouji-kun.&quot;<span class=\"pg\">p.249<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> &quot;I-I&#x27;m sorry... I&#x27;m sorry. I just... couldn&#x27;t help wanting to touch you... even though we&#x27;re just friends, aren&#x27;t we.&quot;<span class=\"pg\">p.250<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Aches during the week apart without seeing him; yearns for his fingers and wonders how to make him yearn for her too — &quot;loving someone too much&quot; is painful.<span class=\"pg\">p.249–250<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Their hands touch on the walk home; she pulls back, determined to stay on his level.<span class=\"pg\">p.249–250<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ichinose-honami-y3v2-p220-1\">← Before: Year 3, Vol. 2 Ch.7 — depth read: Ichinose sees through him<\/button><\/div><\/article>"},{"i":"sc-shiina-hiyori-y3v2-p253-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka shiina-hiyori","q":"shiina hiyori year 3  vol  2 ss  a wavering heart   depth read returns to her dorm holding a single poppy flower  recalling ayanokoji s visit   it s frightening to feel so fulfilled   it s okay  right  to keep on loving him like this  realizes she sees him as a man and has fallen in love  questions whether she can fight his class while in love  and resolves to remain his friend  has fallen in love with him  keeps it secret because they are in different classes","h":"<article class=\"card\" id=\"sc-shiina-hiyori-y3v2-p253-1\"><h3><span class=\"ttl\"><a href=\"../../../people/shiina-hiyori.html#sc-shiina-hiyori-y3v2-p253-1\">Year 3, Vol. 2 SS: A Wavering Heart — depth read<\/a><\/span><span class=\"meta\">Y3V2 · <\/span><span class=\"by\">notes on <a href=\"../../../people/shiina-hiyori.html\">Shiina Hiyori<\/a><\/span><\/h3><p class=\"setup\">Returns to her dorm holding a single poppy flower, recalling Ayanokōji&#x27;s visit.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> &quot;It&#x27;s frightening to feel so fulfilled…&quot;<span class=\"pg\">p.253<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Shiina Hiyori<\/b> &quot;It&#x27;s okay, right...? To keep on loving him like this...&quot;<span class=\"pg\">p.253<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Realizes she sees him as a man and has fallen in love; questions whether she can fight his class while in love, and resolves to remain his friend.<span class=\"pg\">p.253–254<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Has fallen in love with him; keeps it secret because they are in different classes.<span class=\"pg\">p.253–254<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-shiina-hiyori-y3v2-p190-1\">← Before: Year 3, Vol. 2 Ch.6 — depth read: Hiyori avoids, then opens up<\/button><\/div><\/article>"}];
